window.AUTH=window.AUTH||{};window.AUTH["22-227"]={"d":"22-227","id":"2022/22-227","n":"Lac du Flambeau Band of Lake Superior Chippewa Indians v. Coughlin","briefs":[{"k":"petitioner","label":"Brief of petitioners Lac du Flambeau Band of Lake Superior Chippewa Indians, et al.","date":"2023-02-22","url":"https://www.supremecourt.gov/DocketPDF/22/22-227/255277/20230222122719725_No._22-227_Brief_For_Petitioners.pdf","side":"pet","n":58},{"k":"respondent","label":"Brief of respondent Brian W. Coughlin","date":"2023-03-24","url":"https://www.supremecourt.gov/DocketPDF/22/22-227/259850/20230324142248739_resp.%20merits%20brief%20-%20Lac%20du%20Flambeau%20v.%20Coughlin%20-%20No.%2022-227.pdf","side":"res","n":161},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2023-03-31","url":"https://www.supremecourt.gov/DocketPDF/22/22-227/262543/20230331203046570_22-227%20Flambeau%20et%20al.%20v.%20Coughlin.pdf","side":"us","n":109},{"k":"reply","label":"Reply of petitioners Lac du Flambeau Band of Lake Superior Chippewa Indians, et al.","date":"2023-04-13","url":"https://www.supremecourt.gov/DocketPDF/22/22-227/263415/20230413115331797_No.-22-227_Reply_Brief_For_Petitioners.pdf","side":"pet","n":29}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r39_3204.pdf","tr":true,"items":[{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"581 U.S. 468","y":2017,"id":"2016/16-74","sc":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"0":"29","1":"37"}},{"t":"case","label":"Allen v. Gold Country Casino","cite":"464 F.3d 1044","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/464/1044/","sum":"Explaining that immunity “directly protects the sovereign Tribe’s treasury, which is one of the historic purposes of sovereign immunity in general”.","sumSrc":"brief:0","by":{"0":"19"}},{"t":"case","label":"Atlantic Richfield Co. v. Christian","cite":"140 S. Ct. 1335","y":2020,"id":"2019/17-1498","sc":1,"sum":"The Court held that the landowners in this case were potentially responsible parties under the Comprehensive Environmental Response, Compensation, and Liability Act (CERCLA) and thus need the Environmental Protection Agency’s approval to take remedial action.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"29","1":"37","3":"6"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"sum":"The Court held that in determining eligibility for cancellation of removal of a lawful permanent resident who commits a serious crime, an offense listed in 8 U.S.C. § 1182(a)(2) committed during the initial seven years of residence need not be one of the offenses of removal.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Blatchford v. Native Vill. of Noatak","cite":"501 U.S. 775","y":1991,"id":"1990/89-1782","sc":1,"op":1,"sum":"Respondents, Alaska Native villages, brought suit against petitioner, a state official, seeking an order requiring payment to them of money allegedly owed under a state revenue-sharing statute. The District Court dismissed the suit as violating the Eleventh Amendment. The Court of Appeals reversed, first on the ground that 28 U. S. C. § 1362 constituted a congressional abrogation of Eleventh Amendment immunity, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36","1":"21, 31","2":"16","3":"22"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"op":5,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"26, 38, 39","1":"30, 44","2":"16, 22, 23"}},{"t":"case","label":"BP P.L.C. v. Mayor & City Council of Balt.","cite":"141 S. Ct. 1532","y":2021,"id":"2020/19-1189","sc":1,"sum":"Where defendant energy companies premised 28 U. S. C. §1447(d) removal in part on the federal officer removal statute, §1442, the Fourth Circuit erred in holding that it lacked jurisdiction to consider all grounds for removal rejected by the District Court.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"43"}},{"t":"case","label":"Breakthrough Mgmt. Grp., Inc. v. Chukchansi Gold Casino & Resort","cite":"629 F.3d 1173","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/629/1173/","by":{"0":"19"}},{"t":"case","label":"C & L Enters., Inc. v. Citizen Band Potawatomi Indian Tribe of Okla.","cite":"532 U.S. 411","y":2001,"id":"2000/00-292","sc":1,"op":2,"sum":"The Court held that \"under the agreement the Tribe proposed and signed, the Tribe clearly consented to arbitration and to the enforcement of arbitral awards in Oklahoma state court; the Tribe thereby waived its sovereign immunity from C & L's suit.\" Justice Ginsburg wrote for the Court that \"the Tribe agreed, by express contract, to adhere to certain dispute resolution procedures.\".","sumSrc":"Oyez","by":{"0":"4, 20, 50","1":"4, 15, 33","2":"2, 10, 11"}},{"t":"case","label":"California v. Cabazon Band of Mission Indians","cite":"480 U.S. 202","y":1987,"id":"1986/85-1708","sc":1,"sum":"Justice Byron R. White delivered the opinion for a 6-3 court. State laws require the consent of Congress in order to apply to Indian reservations. While the federal government consented to states enforcing criminal laws on reservation land, gambling regulations are types of civil law and therefore not enforceable. The Organized Crime Control Act of 1970 did not grant states the authority to regulate gambling either.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Circuit City Stores, Inc. v. Adams","cite":"532 U.S. 105","y":2001,"id":"2000/99-1379","sc":1,"op":4,"ar":3,"sum":"The Court held that section 1 exemption is confined to transportation workers. \"The wording of [section 1] calls for the application of the maxim ejusdem generis, the statutory canon that 'where general words follow specific words in a statutory enumeration, the general words are construed to embrace only objects similar in nature to those objects enumerated by the preceding specific words,'\" wrote Justice Kennedy.","sumSrc":"Oyez","by":{"0":"34, 35"}},{"t":"case","label":"City of Chi. v. Fulton","cite":"141 S. Ct. 585","y":2021,"id":"2020/19-357","sc":1,"op":1,"sum":"The mere retention of estate property after the filing of a bankruptcy petition does not violate 11 U. S. C. §362(a)(3), which operates as a “stay” of “any act” to “exercise control” over the property of the estate.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"5","1":"39","2":"24"}},{"t":"case","label":"Dellmuth v. Muth","cite":"491 U.S. 223","y":1989,"id":"1988/87-1855","sc":1,"by":{"0":"21, 22, 28, 50","1":"33","2":"33","3":"2, 6"}},{"t":"case","label":"EEOC v. Arabian Am. Oil Co.","cite":"499 U.S. 244","y":1991,"id":"1990/89-1838","sc":1,"sum":"Title VII does not apply extraterritorially to regulate the employment practices of United States firms that employ American citizens abroad. Petitioners' evidence, while not totally lacking in probative value, falls short of demonstrating the clearly expressed affirmative congressional intent that is required to overcome the well-established presumption against statutory extraterritoriality.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26","1":"30","3":"6"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"op":5,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"0":"20, 27, 29","1":"8, 14, 32","2":"7, 11, 12, 19","3":"2, 5"}},{"t":"case","label":"Guam v. United States","cite":"141 S. Ct. 1608","y":2021,"id":"2020/20-382","sc":1,"sum":"A settlement of environmental liabilities must resolve a specific liability under the Comprehensive Environmental Response, Compensation, and Liability Act of 1980 to give rise to a contribution action under that Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"38"}},{"t":"case","label":"Hess v. Port Auth. Trans-Hudson Corp.","cite":"513 U.S. 30","y":1994,"id":"1994/93-1197","sc":1,"ar":1,"sum":"PATH is not entitled to Eleventh Amendment immunity from suit in federal court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40, 41"}},{"t":"case","label":"Hoffman v. Connecticut Dep’t of Income Maint.","cite":"492 U.S. 96","y":1989,"id":"1988/88-412","sc":1,"op":2,"sum":"The judgment is affirmed. 850 F. 2d 50, affirmed. JUSTICE WHITE, joined by THE CHIEF JUSTICE, JUSTICE O'CONNOR, and JUSTICE KENNEDY, concluded that in enacting § 106(c) Congress did not abrogate the Eleventh Amendment immunity of the States. Congress has not made an intention to abrogate unmistakably clear in the provision's language. The narrow scope of the waivers of sovereign immunity as to certain particular …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 27","2":"34"}},{"t":"case","label":"Jama v. Immigration & Customs Enf’t","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Kiowa Tribe of Okla. v. Manufacturing Techs., Inc.","cite":"523 U.S. 751","y":1998,"id":"1997/96-1037","sc":1,"op":3,"sum":"The Court held that Indian tribes enjoy sovereign immunity from civil suits on contracts, whether those contracts involve governmental or commercial activities and whether they were made on or off a reservation.","sumSrc":"Oyez","by":{"0":"17, 19, 21, 23, 26, 48, 49","1":"18, 36, 37","2":"11"}},{"t":"case","label":"Lane v. Pena","cite":"518 U.S. 187","y":1996,"id":"1995/95-365","sc":1,"sum":"Although the related provisions of the 1973 Rehabilitation Act and the 1991 Civil Rights Act might in combination be read as waiving the federal government's sovereign immunity, absent an unambiguous waiver of sovereign immunity, the court cannot permit damages to be awarded.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Law v. Siegel","cite":"571 U.S. 415","y":2014,"id":"2013/12-5196","sc":1,"op":1,"sum":"The Court found that a bankruptcy court may not enforce specific statutory exceptions.","sumSrc":"Oyez","by":{"0":"49","2":"24, 30","3":"17"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"op":5,"sum":"The Court held that the policy of equitable tolling does not apply to the statute of limitations outlined in the Hauge Convention's provision on international child abduction.","sumSrc":"Oyez","by":{"0":"29","1":"37"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"op":9,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"0":"4, 8, 17-21, 36, 48-50","1":"4, 7, 14-15, 17, 21, 31-32, 36, 41, 42","2":"2, 5-7, 9-11, 13-16, 21, 29, 32","3":"2, 10, 17, 24"}},{"t":"case","label":"Montana v. Blackfeet Tribe of Indians","cite":"471 U.S. 759","y":1985,"id":"1984/83-2161","sc":1,"sum":"Montana may not tax respondent's royalty interests from leases issued pursuant to the 1938 Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39","1":"38","2":"12"}},{"t":"case","label":"Morris v. Washington Metro. Area Transit Auth.","cite":"781 F.2d 218","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/781/218/","op":3,"sum":"Describing WMATA as “interstate” entity possessing “three immunities *** added together”.","sumSrc":"brief:3","by":{"0":"40, 41","3":"15"}},{"t":"case","label":"National Farmers Union Ins. Cos. v. Crow Tribe of Indians","cite":"471 U.S. 845","y":1985,"id":"1984/84-320","sc":1,"op":1,"sum":"Respondent Crow Indian minor was struck by a motorcycle in the parking lot of a school located within the Crow Indian Reservation but on land owned by the State of Montana. Through his guardian, the minor brought a damages action in the Crow Tribal Court against petitioner School District, a political subdivision of the State, and obtained a default judgment. Thereafter, the School District and its insurer, also a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 35","1":"41","2":"21"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"580 U.S. 288","y":2017,"url":"https://supreme.justia.com/cases/federal/us/580/288/","sc":1,"by":{"0":"45"}},{"t":"case","label":"Northern States Power Co. v. Prairie Island Mdewakanton Sioux Indian Cmty.","cite":"991 F.2d 458","y":1993,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/991/458/","op":1,"sum":"Holding that Hazardous Materials Transportation Act abrogates tribal sovereign immunity by “allow[ing] preemption cases to be brought in ‘any court of competent jurisdiction,’” because “[e]very relevant subsection of [the Act] contains the language ‘state or political subdivision thereof or Indian tribe’”.","sumSrc":"brief:0","by":{"0":"28"}},{"t":"case","label":"Oklahoma Tax Comm’n v. Citizen Band Potawatomi Indian Tribe of Okla.","cite":"498 U.S. 505","y":1991,"id":"1990/89-1322","sc":1,"sum":"Under the doctrine of tribal sovereign immunity, a State that has not asserted jurisdiction over Indian lands under Public Law 280 may not tax sales of goods to tribesmen occurring on land held in trust for a federally recognized Indian tribe, but is free to collect taxes on such sales to nonmembers of the tribe.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","1":"21, 33, 37","2":"10"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"op":3,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Rimini St., Inc. v. Oracle USA, Inc.","cite":"139 S. Ct. 873","y":2019,"id":"2018/17-1625","sc":1,"sum":"A federal district court’s discretion to award “full costs” to a party in copyright litigation pursuant to 17 U. S. C. §505 is limited to the six categories specified in the general costs statute codified at 28 U. S. C. §§1821 and 1920.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"42"}},{"t":"case","label":"Santa Clara Pueblo v. Martinez","cite":"436 U.S. 49","y":1978,"id":"1977/76-682","sc":1,"op":5,"ar":2,"sum":"Respondents, a female member of the Santa Clara Pueblo and her daughter, brought this action for declaratory and injunctive relief against petitioners, the Pueblo and its Governor, alleging that a Pueblo ordinance that denies tribal membership to the children of female members who marry outside the tribe, but not to similarly situated children of men of that tribe, violates Title I of the Indian Civil Rights Act of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 20, 21, 42","1":"4, 14, 18, 36","2":"2, 9-11"}},{"t":"case","label":"Sossamon v. Texas","cite":"563 U.S. 277","y":2011,"id":"2010/08-1438","sc":1,"sum":"The Court held that a person may not sue a state official in his individual capacity for damages under the Religious Land Use and Institutional Persons Act.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Tennessee Student Assistance Corp. v. Hood","cite":"541 U.S. 440","y":2004,"id":"2003/02-1606","sc":1,"sum":"Instead, the Court ruled that discharging a debt owed to a state in a bankruptcy procedure is different from a suit and therefore not barred by sovereign immunity. \"A bankruptcy court is able to provide the debtor a fresh start in this manner ... because the court's jurisdiction is premised on the debtor and his estate, and not on the creditors,\" wrote the Court.","sumSrc":"Oyez","by":{"0":"49","1":"25","3":"17"}},{"t":"case","label":"Three Affiliated Tribes of Fort Berthold Rsrv. v. Wold Eng’g","cite":"476 U.S. 877","y":1986,"id":"1985/84-1973","sc":1,"op":1,"sum":"Petitioner Indian tribe brought suit against respondent corporation (hereafter respondent) in a North Dakota state court for negligence and breach of contract in connection with respondent's construction of a water-supply system on petitioner's reservation. The trial court dismissed the suit for lack of jurisdiction. The North Dakota Supreme Court held that a North Dakota statute (Chapter 27-19)-which provides that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 23, 48","2":"10, 11, 22"}},{"t":"case","label":"Three Affiliated Tribes of Fort Berthold Rsrv. v. Wold Eng’g, P.C.","cite":"467 U.S. 138","y":1984,"id":"1983/82-629","sc":1,"sum":"The North Dakota statute (Chapter 27-19) governing the Indian civil jurisdiction of the state courts provides that jurisdiction shall extend \"over all civil causes of action which arise on an Indian reservation upon acceptance by Indian citizens.\" North Dakota's Enabling Act provides that all Indian land \"shall remain under the absolute jurisdiction and control of Congress.\" Petitioner Indian Tribe, which had not …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35","3":"20"}},{"t":"case","label":"Torres v. Texas Dep’t of Pub. Safety","cite":"142 S. Ct. 2455","y":2022,"id":"2021/20-603","sc":1,"sum":"By ratifying the Constitution, the States agreed their sovereignty would yield to the national power to raise and support the Armed Forces; Congress may exercise this power to authorize private damages suits against nonconsenting States, as in the Uniformed Services Employment and Reemployment Rights Act of 1994.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36","1":"31"}},{"t":"case","label":"United States v. Atlantic Rsch. Corp.","cite":"551 U.S 128","y":2007,"url":"https://www.courtlistener.com/c/U.S/551/128/","by":{"0":"42"}},{"t":"case","label":"United States v. Cooley","cite":"141 S. Ct. 1638","y":2021,"id":"2020/19-1414","sc":1,"sum":"A tribal police officer has authority to detain temporarily and to search a non-Indian traveling on a public right-of-way running through a reservation for potential violations of state or federal law.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"32","1":"20, 41","3":"11"}},{"t":"case","label":"United States v. Mazurie","cite":"419 U.S. 544","y":1975,"id":"1974/73-1018","sc":1,"sum":"Respondents, who operated a bar on non-Indian land on the outskirts of an unincorporated village within the Wind River Reservation and who had been denied a tribal liquor license by the Wind River Tribes pursuant to their option under 18 U. S. C. § 1161 to regulate the introduction of liquor into Indian country, were convicted at a nonjury trial of introducing spirituous beverages into Indian country in violation of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"United States v. Nordic Vill., Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"op":2,"ar":2,"sum":"After respondent Nordic Village, Inc., filed a petition for relief under Chapter 11 of the Bankruptcy Code, one of its officers withdrew funds from the company's corporate account. He sent part of the money to the Internal Revenue Service (IRS), directing it to apply the funds against his individual tax liability, which it did. In a subsequent adversary proceeding, the Bankruptcy Court permitted Nordic Village's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 20, 27, 42, 45","2":"11, 27, 28, 34","3":"14, 19, 22"}},{"t":"case","label":"Upper Skagit Indian Tribe v. Lundgren","cite":"138 S. Ct. 1649","y":2018,"id":"2017/17-387","sc":1,"op":1,"sum":"The Court held that its prior decision in County of Yakima v. Confederated Tribes and Bands of Yakima Nation addressed only a question of statutory interpretation, not the question whether Indian tribes have sovereign immunity in rem lawsuits.","sumSrc":"Oyez","by":{"0":"20","1":"37"}},{"t":"case","label":"West Virginia v. EPA","cite":"142 S. Ct. 2587","y":2022,"id":"2021/20-1530","sc":1,"sum":"Congress did not grant the Environmental Protection Agency in Section 111(d) of the Clean Air Act the authority to devise emissions caps based on the generation shifting approach the Agency took in the Clean Power Plan.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"31","1":"38, 39","3":"9"}},{"t":"usc","label":"7 U.S.C. § 8310","url":"https://www.law.cornell.edu/uscode/text/7/8310","stext":{"head":"§8310. Cooperation","paras":[[0,"(a) In general"],[0,"To carry out this chapter, the Secretary may cooperate with other Federal agencies, States or political subdivisions of States, national governments of foreign countries, local governments of foreign countries, domestic or international organizations, domestic or international associations, Indian tribes, and other persons."],[0,"(b) Responsibility"],[0,"The person or other entity cooperating with the Secretary shall be responsible for the authority necessary to carry out operations or measures—"],[1,"(1) on all land and property within a foreign country or State, or under the jurisdiction of an Indian tribe, other than on land and property owned or controlled by the United States; and"],[1,"(2) using other facilities and means, as determined by the Secretary."],[0,"(c) Screwworms"],[0,"(1) In general"],[1,"The Secretary may, independently or in cooperation with national governments of foreign countries or international organizations or associations, produce and sell sterile screwworms to any national government of a foreign country or international organization or association, if the Secretary determines that the livestock industry and related industries of the United States will not be adversely affected by the production and sale."],[0,"(2) Proceeds"],[0,"(A) Independent production and sale"],[2,"If the Secretary independently produces and sells sterile screwworms under paragraph (1), the proceeds of the sale shall be—"],[3,"(i) deposited into the Treasury of the United States; and"],[3,"(ii) credited to the account from which the operating expenses of the facility producing the sterile screwworms have been paid."],[0,"(B) Cooperative production and sale"],[0,"(i) In general"],[3,"If the Secretary cooperates to produce and sell sterile screwworms under paragraph (1), the proceeds of the sale shall be divided between the United States and the cooperating national government or international organization or association in a manner determined by the Secretary."],[0,"(ii) Account"],[3,"The United States portion of the proceeds shall be—"],[4,"(I) deposited into the Treasury of the United States; and"],[4,"(II) credited to the account from which the operating expenses of the facility producing the sterile screwworms have been paid."],[0,"(d) Cooperation in program administration"],[0,"The Secretary may cooperate with State authorities, Indian tribe authorities, or other persons in the administration of regulations for the improvement of livestock and livestock products."],[0,"(e) Consultation and coordination with other Federal agencies"],[0,"(1) In general"],[1,"The Secretary shall consult and coordinate with the head of a Federal agency with respect to any activity that is under the jurisdiction of the Federal agency."],[0,"(2) Lead agency"],[1,"Subject to the consultation and coordination requirement in paragraph (1), the Department of Agriculture shall be the lead agency with respect to issues related to pests and diseases of livestock."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/8310?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§8310. Cooperation","tname":"Agriculture","by":{"0":"24"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(27)","(14A)","(41)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"head":"§101. Definitions","tname":"Bankruptcy","by":{"0":"4, 6, 22, 23, 30, 33, 41","1":"28, 28, 1-4, 6-9, 13, 15-17, 20, 22-23, 32, 34, 36, 42, 44-45","2":"1, 2, 31, 31, 3, 5-8, 13-18, 21-23, 30, 31, 32, 34, 32","3":"3, 16"}},{"t":"usc","label":"18 U.S.C. § 229","url":"https://www.law.cornell.edu/uscode/text/18/229","subs":["(a)(1)"],"by":{"0":"38"}},{"t":"usc","label":"25 U.S.C. § 2710","url":"https://www.law.cornell.edu/uscode/text/25/2710","subs":["(d)(7)(A)(ii)"],"stext":{"head":"§2710. Tribal gaming ordinances","paras":[[0,"(a) Jurisdiction over class I and class II gaming activity"],[0,"(1) Class I gaming on Indian lands is within the exclusive jurisdiction of the Indian tribes and shall not be subject to the provisions of this chapter."],[0,"(2) Any class II gaming on Indian lands shall continue to be within the jurisdiction of the Indian tribes, but shall be subject to the provisions of this chapter."],[0,"(b) Regulation of class II gaming activity; net revenue allocation; audits; contracts"],[0,"(1) An Indian tribe may engage in, or license and regulate, class II gaming on Indian lands within such tribe's jurisdiction, if—"],[1,"(A) such Indian gaming is located within a State that permits such gaming for any purpose by any person, organization or entity (and such gaming is not otherwise specifically prohibited on Indian lands by Federal law), and"],[1,"(B) the governing body of the Indian tribe adopts an ordinance or resolution which is approved by the Chairman."],[0,"A separate license issued by the Indian tribe shall be required for each place, facility, or location on Indian lands at which class II gaming is conducted."],[0,"(2) The Chairman shall approve any tribal ordinance or resolution concerning the conduct, or regulation of class II gaming on the Indian lands within the tribe's jurisdiction if such ordinance or resolution provides that—"],[1,"(A) except as provided in paragraph (4), the Indian tribe will have the sole proprietary interest and responsibility for the conduct of any gaming activity;"],[1,"(B) net revenues from any tribal gaming are not to be used for purposes other than—"],[2,"(i) to fund tribal government operations or programs;"],[2,"(ii) to provide for the general welfare of the Indian tribe and its members;"],[2,"(iii) to promote tribal economic development;"],[2,"(iv) to donate to charitable organizations; or"],[2,"(v) to help fund operations of local government agencies;"],[1,"(C) annual outside audits of the gaming, which may be encompassed within existing independent tribal audit systems, will be provided by the Indian tribe to the Commission;"],[1,"(D) all contracts for supplies, services, or concessions for a contract amount in excess of $25,000 annually (except contracts for professional legal or accounting services) relating to such gaming shall be subject to such independent audits;"],[1,"(E) the construction and maintenance of the gaming facility, and the operation of that gaming is conducted in a manner which adequately protects the environment and the public health and safety; and"],[1,"(F) there is an adequate system which—"],[2,"(i) ensures that background investigations are conducted on the primary management officials and key employees of the gaming enterprise and that oversight of such officials and their management is conducted on an ongoing basis; and"],[2,"(ii) includes—"],[3,"(I) tribal licenses for primary management officials and key employees of the gaming enterprise with prompt notification to the Commission of the issuance of such licenses;"],[3,"(II) a standard whereby any person whose prior activities, criminal record, if any, or reputation, habits and associations pose a threat to the public interest or to the effective regulation of gaming, or create or enhance the dangers of unsuitable, unfair, or illegal practices and methods and activities in the conduct of gaming shall not be eligible for employment; and"],[3,"(III) notification by the Indian tribe to the Commission of the results of such background check before the issuance of any of such licenses."],[0,"(3) Net revenues from any class II gaming activities conducted or licensed by any Indian tribe may be used to make per capita payments to members of the Indian tribe only if—"],[1,"(A) the Indian tribe has prepared a plan to allocate revenues to uses authorized by paragraph (2)(B);"],[1,"(B) the plan is approved by the Secretary as adequate, particularly with respect to uses described in clause (i) or (iii) of paragraph (2)(B);"],[1,"(C) the interests of minors and other legally incompetent persons who are entitled to receive any of the per capita payments are protected and preserved and the per capita payments are disbursed to the parents or legal guardian of such minors or legal incompetents in such amounts as may be necessary for the health, education, or welfare, of the minor or other legally incompetent person under a plan approved by the Secretary and the governing body of the Indian tribe; and"],[1,"(D) the per capita payments are subject to Federal taxation and tribes notify members of such tax liability when payments are made."],[0,"(4)(A) A tribal ordinance or resolution may provide for the licensing or regulation of class II gaming activities owned by any person or entity other than the Indian tribe and conducted on Indian lands, only if the tribal licensing requirements include the requirements described in the subclauses of subparagraph (B)(i) and are at least as restrictive as those established by State law governing similar gaming within the jurisdiction of the State within which such Indian lands are located. No person or entity, other than the Indian tribe, shall be eligible to receive a tribal license to own a class II gaming activity conducted on Indian lands within the jurisdiction of the Indian tribe if such person or entity would not be eligible to receive a State license to conduct the same activity within the jurisdiction of the State."],[0,"(B)(i) The provisions of subparagraph (A) of this paragraph and the provisions of subparagraphs (A) and (B) of paragraph (2) shall not bar the continued operation of an individually owned class II gaming operation that was operating on September 1, 1986, if—"],[1,"(I) such gaming operation is licensed and regulated by an Indian tribe pursuant to an ordinance reviewed and approved by the Commission in accordance with section 2712 of this title,"],[1,"(II) income to the Indian tribe from such gaming is used only for the purposes described in paragraph (2)(B) of this subsection,"],[1,"(III) not less than 60 percent of the net revenues is income to the Indian tribe, and"],[1,"(IV) the owner of such gaming operation pays an appropriate assessment to the National Indian Gaming Commission under section 2717(a)(1) of this title for regulation of such gaming."],[0,"(ii) The exemption from the application of this subsection provided under this subparagraph may not be transferred to any person or entity and shall remain in effect only so long as the gaming activity remains within the same nature and scope as operated on October 17, 1988."],[0,"(iii) Within sixty days of October 17, 1988, the Secretary shall prepare a list of each individually owned gaming operation to which clause (i) applies and shall publish such list in the Federal Register."],[0,"(c) Issuance of gaming license; certificate of self-regulation"],[0,"(1) The Commission may consult with appropriate law enforcement officials concerning gaming licenses issued by an Indian tribe and shall have thirty days to notify the Indian tribe of any objections to issuance of such license."],[0,"(2) If, after the issuance of a gaming license by an Indian tribe, reliable information is received from the Commission indicating that a primary management official or key employee does not meet the standard established under subsection (b)(2)(F)(ii)(II), the Indian tribe shall suspend such license and, after notice and hearing, may revoke such license."],[0,"(3) Any Indian tribe which operates a class II gaming activity and which—"],[1,"(A) has continuously conducted such activity for a period of not less than three years, including at least one year after October 17, 1988; and"],[1,"(B) has otherwise complied with the provisions of this section 1"],[0,"may petition the Commission for a certificate of self-regulation."],[0,"(4) The Commission shall issue a certificate of self-regulation if it determines from available information, and after a hearing if requested by the tribe, that the tribe has—"],[1,"(A) conducted its gaming activity in a manner which—"],[2,"(i) has resulted in an effective and honest accounting of all revenues;"],[2,"(ii) has resulted in a reputation for safe, fair, and honest operation of the activity; and"],[2,"(iii) has been generally free of evidence of criminal or dishonest activity;"],[1,"(B) adopted and is implementing adequate systems for—"],[2,"(i) accounting for all revenues from the activity;"],[2,"(ii) investigation, licensing, and monitoring of all employees of the gaming activity; and"],[2,"(iii) investigation, enforcement and prosecution of violations of its gaming ordinance and regulations; and"],[1,"(C) conducted the operation on a fiscally and economically sound basis."],[0,"(5) During any year in which a tribe has a certificate for self-regulation—"],[1,"(A) the tribe shall not be subject to the provisions of paragraphs (1), (2), (3), and (4) of section 2706(b) of this title;"],[1,"(B) the tribe shall continue to submit an annual independent audit as required by subsection (b)(2)(C) and shall submit to the Commission a complete resume on all employees hired and licensed by the tribe subsequent to the issuance of a certificate of self-regulation; and"],[1,"(C) the Commission may not assess a fee on such activity pursuant to section 2717 of this title in excess of one quarter of 1 per centum of the gross revenue."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/2710?type=usc&year=mostrecent&link-type=html"},"head":"§2710. Tribal gaming ordinances","tname":"Indians","by":{"0":"24, 28","1":"35","2":"19"}},{"t":"usc","label":"28 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/28/158","subs":["(d)"],"stext":{"head":"§158. Appeals","paras":[[0,"(a) The district courts of the United States shall have jurisdiction to hear appeals 1"],[1,"(1) from final judgments, orders, and decrees;"],[1,"(2) from interlocutory orders and decrees issued under section 1121(d) of title 11 increasing or reducing the time periods referred to in section 1121 of such title; and"],[1,"(3) with leave of the court, from other interlocutory orders and decrees;"],[0,"of bankruptcy judges entered in cases and proceedings referred to the bankruptcy judges under section 157 of this title. An appeal under this subsection shall be taken only to the district court for the judicial district in which the bankruptcy judge is serving."],[0,"(b)(1) The judicial council of a circuit shall establish a bankruptcy appellate panel service composed of bankruptcy judges of the districts in the circuit who are appointed by the judicial council in accordance with paragraph (3), to hear and determine, with the consent of all the parties, appeals under subsection (a) unless the judicial council finds that—"],[1,"(A) there are insufficient judicial resources available in the circuit; or"],[1,"(B) establishment of such service would result in undue delay or increased cost to parties in cases under title 11."],[0,"Not later than 90 days after making the finding, the judicial council shall submit to the Judicial Conference of the United States a report containing the factual basis of such finding."],[0,"(2)(A) A judicial council may reconsider, at any time, the finding described in paragraph (1)."],[0,"(B) On the request of a majority of the district judges in a circuit for which a bankruptcy appellate panel service is established under paragraph (1), made after the expiration of the 1-year period beginning on the date such service is established, the judicial council of the circuit shall determine whether a circumstance specified in subparagraph (A) or (B) of such paragraph exists."],[0,"(C) On its own motion, after the expiration of the 3-year period beginning on the date a bankruptcy appellate panel service is established under paragraph (1), the judicial council of the circuit may determine whether a circumstance specified in subparagraph (A) or (B) of such paragraph exists."],[0,"(D) If the judicial council finds that either of such circumstances exists, the judicial council may provide for the completion of the appeals then pending before such service and the orderly termination of such service."],[0,"(3) Bankruptcy judges appointed under paragraph (1) shall be appointed and may be reappointed under such paragraph."],[0,"(4) If authorized by the Judicial Conference of the United States, the judicial councils of 2 or more circuits may establish a joint bankruptcy appellate panel comprised of bankruptcy judges from the districts within the circuits for which such panel is established, to hear and determine, upon the consent of all the parties, appeals under subsection (a) of this section."],[0,"(5) An appeal to be heard under this subsection shall be heard by a panel of 3 members of the bankruptcy appellate panel service, except that a member of such service may not hear an appeal originating in the district for which such member is appointed or designated under section 152 of this title."],[0,"(6) Appeals may not be heard under this subsection by a panel of the bankruptcy appellate panel service unless the district judges for the district in which the appeals occur, by majority vote, have authorized such service to hear and determine appeals originating in such district."],[0,"(c)(1) Subject to subsections (b) and (d)(2), each appeal under subsection (a) shall be heard by a 3-judge panel of the bankruptcy appellate panel service established under subsection (b)(1) unless—"],[1,"(A) the appellant elects at the time of filing the appeal; or"],[1,"(B) any other party elects, not later than 30 days after service of notice of the appeal;"],[0,"to have such appeal heard by the district court."],[0,"(2) An appeal under subsections (a) and (b) of this section shall be taken in the same manner as appeals in civil proceedings generally are taken to the courts of appeals from the district courts and in the time provided by Rule 8002 of the Bankruptcy Rules."],[0,"(d)(1) The courts of appeals shall have jurisdiction of appeals from all final decisions, judgments, orders, and decrees entered under subsections (a) and (b) of this section."],[0,"(2)(A) The appropriate court of appeals shall have jurisdiction of appeals described in the first sentence of subsection (a) if the bankruptcy court, the district court, or the bankruptcy appellate panel involved, acting on its own motion or on the request of a party to the judgment, order, or decree described in such first sentence, or all the appellants and appellees (if any) acting jointly, certify that—"],[1,"(i) the judgment, order, or decree involves a question of law as to which there is no controlling decision of the court of appeals for the circuit or of the Supreme Court of the United States, or involves a matter of public importance;"],[1,"(ii) the judgment, order, or decree involves a question of law requiring resolution of conflicting decisions; or"],[1,"(iii) an immediate appeal from the judgment, order, or decree may materially advance the progress of the case or proceeding in which the appeal is taken;"],[0,"and if the court of appeals authorizes the direct appeal of the judgment, order, or decree."],[0,"(B) If the bankruptcy court, the district court, or the bankruptcy appellate panel—"],[1,"(i) on its own motion or on the request of a party, determines that a circumstance specified in clause (i), (ii), or (iii) of subparagraph (A) exists; or"],[1,"(ii) receives a request made by a majority of the appellants and a majority of appellees (if any) to make the certification described in subparagraph (A);"],[0,"then the bankruptcy court, the district court, or the bankruptcy appellate panel shall make the certification described in subparagraph (A)."],[0,"(C) The parties may supplement the certification with a short statement of the basis for the certification."],[0,"(D) An appeal under this paragraph does not stay any proceeding of the bankruptcy court, the district court, or the bankruptcy appellate panel from which the appeal is taken, unless the respective bankruptcy court, district court, or bankruptcy appellate panel, or the court of appeals in which the appeal is pending, issues a stay of such proceeding pending the appeal."],[0,"(E) Any request under subparagraph (B) for certification shall be made not later than 60 days after the entry of the judgment, order, or decree."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/158?type=usc&year=mostrecent&link-type=html"},"head":"§158. Appeals","tname":"Judiciary and Judicial Procedure","by":{"0":"8","2":"5"}},{"t":"usc","label":"33 U.S.C. § 1362","url":"https://www.law.cornell.edu/uscode/text/33/1362","subs":["(4)","(5)"],"stext":{"head":"§1362. Definitions","paras":[[0,"Except as otherwise specifically provided, when used in this chapter:"],[0,"(1) The term \"State water pollution control agency\" means the State agency designated by the Governor having responsibility for enforcing State laws relating to the abatement of pollution."],[0,"(2) The term \"interstate agency\" means an agency of two or more States established by or pursuant to an agreement or compact approved by the Congress, or any other agency of two or more States, having substantial powers or duties pertaining to the control of pollution as determined and approved by the Administrator."],[0,"(3) The term \"State\" means a State, the District of Columbia, the Commonwealth of Puerto Rico, the Virgin Islands, Guam, American Samoa, the Commonwealth of the Northern Mariana Islands, and the Trust Territory of the Pacific Islands."],[0,"(4) The term \"municipality\" means a city, town, borough, county, parish, district, association, or other public body created by or pursuant to State law and having jurisdiction over disposal of sewage, industrial wastes, or other wastes, or an Indian tribe or an authorized Indian tribal organization, or a designated and approved management agency under section 1288 of this title."],[0,"(5) The term \"person\" means an individual, corporation, partnership, association, State, municipality, commission, or political subdivision of a State, or any interstate body."],[0,"(6) The term \"pollutant\" means dredged spoil, solid waste, incinerator residue, sewage, garbage, sewage sludge, munitions, chemical wastes, biological materials, radioactive materials, heat, wrecked or discarded equipment, rock, sand, cellar dirt and industrial, municipal, and agricultural waste discharged into water. This term does not mean (A) \"sewage from vessels or a discharge incidental to the normal operation of a vessel of the Armed Forces\" within the meaning of section 1322 of this title; or (B) water, gas, or other material which is injected into a well to facilitate production of oil or gas, or water derived in association with oil or gas production and disposed of in a well, if the well used either to facilitate production or for disposal purposes is approved by authority of the State in which the well is located, and if such State determines that such injection or disposal will not result in the degradation of ground or surface water resources."],[0,"(7) The term \"navigable waters\" means the waters of the United States, including the territorial seas."],[0,"(8) The term \"territorial seas\" means the belt of the seas measured from the line of ordinary low water along that portion of the coast which is in direct contact with the open sea and the line marking the seaward limit of inland waters, and extending seaward a distance of three miles."],[0,"(9) The term \"contiguous zone\" means the entire zone established or to be established by the United States under article 24 of the Convention of the Territorial Sea and the Contiguous Zone."],[0,"(10) The term \"ocean\" means any portion of the high seas beyond the contiguous zone."],[0,"(11) The term \"effluent limitation\" means any restriction established by a State or the Administrator on quantities, rates, and concentrations of chemical, physical, biological, and other constituents which are discharged from point sources into navigable waters, the waters of the contiguous zone, or the ocean, including schedules of compliance."],[0,"(12) The term \"discharge of a pollutant\" and the term \"discharge of pollutants\" each means (A) any addition of any pollutant to navigable waters from any point source, (B) any addition of any pollutant to the waters of the contiguous zone or the ocean from any point source other than a vessel or other floating craft."],[0,"(13) The term \"toxic pollutant\" means those pollutants, or combinations of pollutants, including disease-causing agents, which after discharge and upon exposure, ingestion, inhalation or assimilation into any organism, either directly from the environment or indirectly by ingestion through food chains, will, on the basis of information available to the Administrator, cause death, disease, behavioral abnormalities, cancer, genetic mutations, physiological malfunctions (including malfunctions in reproduction) or physical deformations, in such organisms or their offspring."],[0,"(14) The term \"point source\" means any discernible, confined and discrete conveyance, including but not limited to any pipe, ditch, channel, tunnel, conduit, well, discrete fissure, container, rolling stock, concentrated animal feeding operation, or vessel or other floating craft, from which pollutants are or may be discharged. This term does not include agricultural stormwater discharges and return flows from irrigated agriculture."],[0,"(15) The term \"biological monitoring\" shall mean the determination of the effects on aquatic life, including accumulation of pollutants in tissue, in receiving waters due to the discharge of pollutants (A) by techniques and procedures, including sampling of organisms representative of appropriate levels of the food chain appropriate to the volume and the physical, chemical, and biological characteristics of the effluent, and (B) at appropriate frequencies and locations."],[0,"(16) The term \"discharge\" when used without qualification includes a discharge of a pollutant, and a discharge of pollutants."],[0,"(17) The term \"schedule of compliance\" means a schedule of remedial measures including an enforceable sequence of actions or operations leading to compliance with an effluent limitation, other limitation, prohibition, or standard."],[0,"(18) The term \"industrial user\" means those industries identified in the Standard Industrial Classification Manual, Bureau of the Budget, 1967, as amended and supplemented, under the category of \"Division D—Manufacturing\" and such other classes of significant waste producers as, by regulation, the Administrator deems appropriate."],[0,"(19) The term \"pollution\" means the man-made or man-induced alteration of the chemical, physical, biological, and radiological integrity of water."],[0,"(20) The term \"medical waste\" means isolation wastes; infectious agents; human blood and blood products; pathological wastes; sharps; body parts; contaminated bedding; surgical wastes and potentially contaminated laboratory wastes; dialysis wastes; and such additional medical items as the Administrator shall prescribe by regulation."],[0,"(21) Coastal recreation waters.—"],[1,"(A) In general.—The term \"coastal recreation waters\" means—"],[2,"(i) the Great Lakes; and"],[2,"(ii) marine coastal waters (including coastal estuaries) that are designated under section 1313(c) of this title by a State for use for swimming, bathing, surfing, or similar water contact activities."],[1,"(B) Exclusions.—The term \"coastal recreation waters\" does not include—"],[2,"(i) inland waters; or"],[2,"(ii) waters upstream of the mouth of a river or stream having an unimpaired natural connection with the open sea."],[0,"(22) Floatable material.—"],[1,"(A) In general.—The term \"floatable material\" means any foreign matter that may float or remain suspended in the water column."],[1,"(B) Inclusions.—The term \"floatable material\" includes—"],[2,"(i) plastic;"],[2,"(ii) aluminum cans;"],[2,"(iii) wood products;"],[2,"(iv) bottles; and"],[2,"(v) paper products."],[0,"(23) Pathogen indicator.—The term \"pathogen indicator\" means a substance that indicates the potential for human infectious disease."],[0,"(24) Oil and gas exploration and production.—The term \"oil and gas exploration, production, processing, or treatment operations or transmission facilities\" means all field activities or operations associated with exploration, production, processing, or treatment operations, or transmission facilities, including activities necessary to prepare a site for drilling and for the movement and placement of drilling equipment, whether or not such field activities or operations may be considered to be construction activities."],[0,"(25) Recreational vessel.—"],[1,"(A) In general.—The term \"recreational vessel\" means any vessel that is—"],[2,"(i) manufactured or used primarily for pleasure; or"],[2,"(ii) leased, rented, or chartered to a person for the pleasure of that person."],[1,"(B) Exclusion.—The term \"recreational vessel\" does not include a vessel that is subject to Coast Guard inspection and that—"],[2,"(i) is engaged in commercial use; or"],[2,"(ii) carries paying passengers."],[0,"(26) Treatment works.—The term \"treatment works\" has the meaning given the term in section 1292 of this title."],[0,"(27) Green infrastructure.—The term \"green infrastructure\" means the range of measures that use plant or soil systems, permeable pavement or other permeable surfaces or substrates, stormwater harvest and reuse, or landscaping to store, infiltrate, or evapotranspirate stormwater and reduce flows to sewer systems or to surface waters."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1362?type=usc&year=mostrecent&link-type=html"},"head":"§1362. Definitions","tname":"Navigation and Navigable Waters","by":{"0":"25","1":"35","2":"19, 19"}},{"t":"usc","label":"42 U.S.C. § 300f","url":"https://www.law.cornell.edu/uscode/text/42/300f","subs":["(10)","(12)"],"stext":{"head":"§300f. Definitions","paras":[[0,"For purposes of this subchapter:"],[1,"(1) The term \"primary drinking water regulation\" means a regulation which—"],[2,"(A) applies to public water systems;"],[2,"(B) specifies contaminants which, in the judgment of the Administrator, may have any adverse effect on the health of persons;"],[2,"(C) specifies for each such contaminant either—"],[3,"(i) a maximum contaminant level, if, in the judgment of the Administrator, it is economically and technologically feasible to ascertain the level of such contaminant in water in public water systems, or"],[3,"(ii) if, in the judgment of the Administrator, it is not economically or technologically feasible to so ascertain the level of such contaminant, each treatment technique known to the Administrator which leads to a reduction in the level of such contaminant sufficient to satisfy the requirements of section 300g–1 of this title; and"],[2,"(D) contains criteria and procedures to assure a supply of drinking water which dependably complies with such maximum contaminant levels; including accepted methods for quality control and testing procedures to insure compliance with such levels and to insure proper operation and maintenance of the system, and requirements as to (i) the minimum quality of water which may be taken into the system and (ii) siting for new facilities for public water systems."],[1,"At any time after promulgation of a regulation referred to in this paragraph, the Administrator may add equally effective quality control and testing procedures by guidance published in the Federal Register. Such procedures shall be treated as an alternative for public water systems to the quality control and testing procedures listed in the regulation."],[1,"(2) The term \"secondary drinking water regulation\" means a regulation which applies to public water systems and which specifies the maximum contaminant levels which, in the judgment of the Administrator, are requisite to protect the public welfare. Such regulations may apply to any contaminant in drinking water (A) which may adversely affect the odor or appearance of such water and consequently may cause a substantial number of the persons served by the public water system providing such water to discontinue its use, or (B) which may otherwise adversely affect the public welfare. Such regulations may vary according to geographic and other circumstances."],[1,"(3) The term \"maximum contaminant level\" means the maximum permissible level of a contaminant in water which is delivered to any user of a public water system."],[1,"(4) Public water system.—"],[2,"(A) In general.—The term \"public water system\" means a system for the provision to the public of water for human consumption through pipes or other constructed conveyances, if such system has at least fifteen service connections or regularly serves at least twenty-five individuals. Such term includes (i) any collection, treatment, storage, and distribution facilities under control of the operator of such system and used primarily in connection with such system, and (ii) any collection or pretreatment storage facilities not under such control which are used primarily in connection with such system."],[2,"(B) Connections.—"],[3,"(i) In general.—For purposes of subparagraph (A), a connection to a system that delivers water by a constructed conveyance other than a pipe shall not be considered a connection, if—"],[4,"(I) the water is used exclusively for purposes other than residential uses (consisting of drinking, bathing, and cooking, or other similar uses);"],[4,"(II) the Administrator or the State (in the case of a State exercising primary enforcement responsibility for public water systems) determines that alternative water to achieve the equivalent level of public health protection provided by the applicable national primary drinking water regulation is provided for residential or similar uses for drinking and cooking; or"],[4,"(III) the Administrator or the State (in the case of a State exercising primary enforcement responsibility for public water systems) determines that the water provided for residential or similar uses for drinking, cooking, and bathing is centrally treated or treated at the point of entry by the provider, a pass-through entity, or the user to achieve the equivalent level of protection provided by the applicable national primary drinking water regulations."],[3,"(ii) Irrigation districts.—An irrigation district in existence prior to May 18, 1994, that provides primarily agricultural service through a piped water system with only incidental residential or similar use shall not be considered to be a public water system if the system or the residential or similar users of the system comply with subclause (II) or (III) of clause (i)."],[2,"(C) Transition period.—A water supplier that would be a public water system only as a result of modifications made to this paragraph by the Safe Drinking Water Act Amendments of 1996 shall not be considered a public water system for purposes of the Act until the date that is two years after August 6, 1996. If a water supplier does not serve 15 service connections (as defined in subparagraphs (A) and (B)) or 25 people at any time after the conclusion of the 2-year period, the water supplier shall not be considered a public water system."],[1,"(5) The term \"supplier of water\" means any person who owns or operates a public water system."],[1,"(6) The term \"contaminant\" means any physical, chemical, biological, or radiological substance or matter in water."],[1,"(7) The term \"Administrator\" means the Administrator of the Environmental Protection Agency."],[1,"(8) The term \"Agency\" means the Environmental Protection Agency."],[1,"(9) The term \"Council\" means the National Drinking Water Advisory Council established under section 300j–5 of this title."],[1,"(10) The term \"municipality\" means a city, town, or other public body created by or pursuant to State law, or an Indian Tribe."],[1,"(11) The term \"Federal agency\" means any department, agency, or instrumentality of the United States."],[1,"(12) The term \"person\" means an individual, corporation, company, association, partnership, State, municipality, or Federal agency (and includes officers, employees, and agents of any corporation, company, association, State, municipality, or Federal agency)."],[1,"(13)(A) Except as provided in subparagraph (B), the term \"State\" includes, in addition to the several States, only the District of Columbia, Guam, the Commonwealth of Puerto Rico, the Northern Mariana Islands, the Virgin Islands, American Samoa, and the Trust Territory of the Pacific Islands."],[1,"(B) For purposes of section 300j–12 of this title, the term \"State\" means each of the 50 States, the District of Columbia, and the Commonwealth of Puerto Rico."],[1,"(14) The term \"Indian Tribe\" means any Indian tribe having a Federally recognized governing body carrying out substantial governmental duties and powers over any area. For purposes of sections 300j–12, 300j–19a, and 300j–19b of this title, the term includes any Native village (as defined in section 1602(c) of title 43)."],[1,"(15) Community water system.—The term \"community water system\" means a public water system that—"],[2,"(A) serves at least 15 service connections used by year-round residents of the area served by the system; or"],[2,"(B) regularly serves at least 25 year-round residents."],[1,"(16) Noncommunity water system.—The term \"noncommunity water system\" means a public water system that is not a community water system."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/300f?type=usc&year=mostrecent&link-type=html"},"head":"§300f. Definitions","tname":"The Public Health and Welfare","by":{"0":"25","1":"35, 35, 35","2":"19, 19"}},{"t":"usc","label":"49 U.S.C. § 5121","url":"https://www.law.cornell.edu/uscode/text/49/5121","subs":["(g)"],"stext":{"head":"§5121. Administrative","paras":[[0,"(a) General Authority.—To carry out this chapter, the Secretary may investigate, conduct tests, make reports, issue subpenas, conduct hearings, require the production of records and property, take depositions, and conduct research, development, demonstration, and training activities. Except as provided in subsections (c) and (d), after notice and an opportunity for a hearing, the Secretary may issue an order requiring compliance with this chapter or a regulation prescribed, or an order, special permit, or approval issued, under this chapter."],[0,"(b) Records, Reports, and Information.—A person subject to this chapter shall—"],[1,"(1) maintain records and property, make reports, and provide information the Secretary by regulation or order requires; and"],[1,"(2) make the records, property, reports, and information available for inspection when the Secretary undertakes an investigation or makes a request."],[0,"(c) Inspections and Investigations.—"],[1,"(1) In general.—A designated officer, employee, or agent of the Secretary—"],[2,"(A) may inspect and investigate, at a reasonable time and in a reasonable manner, records and property relating to a function described in section 5103(b)(1);"],[2,"(B) except in the case of packaging immediately adjacent to its hazardous material contents, may gain access to, open, and examine a package offered for, or in, transportation when the officer, employee, or agent has an objectively reasonable and articulable belief that the package may contain a hazardous material;"],[2,"(C) may remove from transportation a package or related packages in a shipment offered for or in transportation for which—"],[3,"(i) such officer, employee, or agent has an objectively reasonable and articulable belief that the package may pose an imminent hazard; and"],[3,"(ii) such officer, employee, or agent contemporaneously documents such belief in accordance with procedures set forth in guidance or regulations prescribed under subsection (e);"],[2,"(D) may gather information from the offeror, carrier, packaging manufacturer or tester, or other person responsible for the package, to ascertain the nature and hazards of the contents of the package;"],[2,"(E) as necessary, under terms and conditions specified by the Secretary, may order the offeror, carrier, packaging manufacturer or tester, or other person responsible for the package to have the package transported to, opened, and the contents examined and analyzed, at a facility appropriate for the conduct of such examination and analysis;"],[2,"(F) when safety might otherwise be compromised, may authorize properly qualified personnel to assist in the activities conducted under this subsection; and"],[2,"(G) shall provide to the affected offeror, carrier, packaging manufacturer or tester, or other person responsible for the package reasonable notice of—"],[3,"(i) his or her decision to exercise his or her authority under paragraph (1);"],[3,"(ii) any findings made; and"],[3,"(iii) any actions being taken as a result of a finding of noncompliance."],[1,"(2) Display of credentials.—An officer, employee, or agent acting under this subsection shall display proper credentials, in person or in writing, when requested."],[1,"(3) Safe resumption of transportation.—In instances when, as a result of an inspection or investigation under this subsection, an imminent hazard is not found to exist, the Secretary, in accordance with procedures set forth in regulations prescribed under subsection (e), shall assist—"],[2,"(A) in the safe and prompt resumption of transportation of the package concerned; or"],[2,"(B) in any case in which the hazardous material being transported is perishable, in the safe and expeditious resumption of transportation of the perishable hazardous material."],[0,"(d) Emergency Orders.—"],[1,"(1) In general.—If, upon inspection, investigation, testing, or research, the Secretary determines that a violation of a provision of this chapter, or a regulation prescribed under this chapter, or an unsafe condition or practice, constitutes or is causing an imminent hazard, the Secretary may issue or impose emergency restrictions, prohibitions, recalls, or out-of-service orders, without notice or an opportunity for a hearing, but only to the extent necessary to abate the imminent hazard."],[1,"(2) Written orders.—The action of the Secretary under paragraph (1) shall be in a written emergency order that—"],[2,"(A) describes the violation, condition, or practice that constitutes or is causing the imminent hazard;"],[2,"(B) states the restrictions, prohibitions, recalls, or out-of-service orders issued or imposed; and"],[2,"(C) describes the standards and procedures for obtaining relief from the order."],[1,"(3) Opportunity for review.—After taking action under paragraph (1), the Secretary shall provide for review of the action under section 554 of title 5 if a petition for review is filed within 20 calendar days of the date of issuance of the order for the action."],[1,"(4) Expiration of effectiveness of order.—If a petition for review of an action is filed under paragraph (3) and the review under that paragraph is not completed by the end of the 30-day period beginning on the date the petition is filed, the action shall cease to be effective at the end of such period unless the Secretary determines, in writing, that the imminent hazard providing a basis for the action continues to exist."],[1,"(5) Out-of-service order defined.—In this subsection, the term \"out-of-service order\" means a requirement that an aircraft, vessel, motor vehicle, train, railcar, locomotive, other vehicle, transport unit, transport vehicle, freight container, potable tank, or other package not be moved until specified conditions have been met."],[0,"(e) Regulations.—"],[1,"(1) Temporary regulations.—Not later than 60 days after the date of enactment of the Hazardous Materials Transportation Safety and Security Reauthorization Act of 2005, the Secretary shall issue temporary regulations to carry out subsections (c) and (d). The temporary regulations shall expire on the date of issuance of the regulations under paragraph (2)."],[1,"(2) Final regulations.—Not later than 1 year after such date of enactment, the Secretary shall issue regulations to carry out subsections (c) and (d) in accordance with subchapter II of chapter 5 of title 5."],[1,"(3) Matters to be addressed.—The regulations issued under this subsection shall address—"],[2,"(A) the safe and expeditious resumption of transportation of perishable hazardous material, including radiopharmaceuticals and other medical products, that may require timely delivery due to life-threatening situations;"],[2,"(B) the means by which—"],[3,"(i) noncompliant packages that present an imminent hazard are placed out-of-service until the condition is corrected; and"],[3,"(ii) noncompliant packages that do not present a hazard are moved to their final destination;"],[2,"(C) appropriate training and equipment for inspectors; and"],[2,"(D) the proper closure of packaging in accordance with the hazardous material regulations."],[0,"(f) Facility, Staff, and Reporting System on Risks, Emergencies, and Actions.—(1) The Secretary shall—"],[1,"(A) maintain a facility and technical staff sufficient to provide, within the United States Government, the capability of evaluating a risk related to the transportation of hazardous material and material alleged to be hazardous;"],[1,"(B) maintain a central reporting system and information center capable of providing information and advice to law enforcement and firefighting personnel, other interested individuals, and officers and employees of the Government and State and local governments on meeting an emergency related to the transportation of hazardous material; and"],[1,"(C) conduct a continuous review on all aspects of transporting hazardous material to decide on and take appropriate actions to ensure safe transportation of hazardous material."],[0,"(2) Paragraph (1) of this subsection does not prevent the Secretary from making a contract with a private entity for use of a supplemental reporting system and information center operated and maintained by the contractor."],[0,"(g) Grants and Cooperative Agreements.—The Secretary may enter into grants and cooperative agreements with a person, agency, or instrumentality of the United States, a unit of State or local government, an Indian tribe, a foreign government (in coordination with the Department of State), an educational institution, or other appropriate entity—"],[1,"(1) to expand risk assessment and emergency response capabilities with respect to the safety and security of transportation of hazardous material;"],[1,"(2) to enhance emergency communications capacity as determined necessary by the Secretary, including the use of integrated, interoperable emergency communications technologies where appropriate;"],[1,"(3) to conduct research, development, demonstration, risk assessment, and emergency response planning and training activities; or"],[1,"(4) to otherwise carry out this chapter."],[0,"(h) Report.—The Secretary shall, once every 2 years, prepare and make available to the public on the Department of Transportation's Internet Web site a comprehensive report on the transportation of hazardous materials during the preceding 2 calendar years. The report shall include—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/5121?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5121. Administrative","tname":"Transportation","by":{"0":"24"}},{"t":"law","label":"Pub. L. No. 95-598","url":"https://www.govinfo.gov/link/statute/92/2549","by":{"0":"5"}},{"t":"law","label":"Pub. L. No. 103-394","url":"https://www.govinfo.gov/link/statute/108/4106","by":{"0":"5","2":"25"}},{"t":"reg","label":"7 C.F.R. § 205.2","url":"https://www.ecfr.gov/current/title-7/section-205.2","by":{"0":"34","1":"34","3":"13"}},{"t":"case","label":"Ali v. Federal Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Allen v. Cooper","cite":"140 S. Ct. 994","y":2020,"id":"2019/18-877","sc":1,"sum":"The Court held that the Copyright Remedy Clarification Act was not a valid abrogation of state sovereign immunity to allow authors of original expression to sue states who infringe their federal copyrights.","sumSrc":"Oyez","by":{"1":"12, 31"}},{"t":"case","label":"Bullard v. Blue Hills Bank","cite":"575 U.S. 496","y":2015,"id":"2014/14-116","sc":1,"sum":"The Court held that a bankruptcy court’s order denying confirmation of a repayment plan is not a final order for the purpose of immediate appeal.","sumSrc":"Oyez","by":{"1":"5"}},{"t":"case","label":"Central Virginia Cmty. Coll. v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"op":1,"sum":"The Court ruled that states cannot invoke sovereign immunity as a defense in bankruptcy proceedings. Rather than ruling on the power of Congress under the Bankruptcy Clause to waive states' immunity, as the bankruptcy court did, the Court held that ratification of the Clause itself involved a subordination of state sovereign immunity.","sumSrc":"Oyez","by":{"1":"11, 24, 30, 31, 32","2":"26","3":"20, 22"}},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"sum":"The Court held that Indian Regulatory Gaming Act does not create such an exemption. The Court reasoned that despite its parenthetical reference, the language outside the parenthetical was unambiguous and the subsection applied only to Internal Revenue Code provisions that concerned the reporting and withholding of taxes.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Cotton Petroleum Corp. v. New Mexico","cite":"490 U.S. 163","y":1989,"id":"1988/87-1327","sc":1,"sum":"The State may validly impose severance taxes on the same onreservation production of oil and gas by non-Indian lessees as is subject to the Tribe's own severance tax.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Czyzewski v. Jevic Holding Corp.","cite":"580 U.S. 451","y":2017,"id":"2016/15-649","sc":1,"sum":"The Court determined that bankruptcy court cannot authorize a distribution of settlement proceeds in a manner that does not comply with the Bankruptcy Code’s priority distribution scheme.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Digital Realty Tr., Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Dole Food Co. v. Patrickson","cite":"538 U.S. 468","y":2003,"id":"2002/01-593","sc":1,"sum":"The Court held, 7-2, that a foreign state must itself own a majority of the shares of a corporation if the corporation is to be deemed an instrumentality of the state under the provisions of the FSIA and, 9-0, that instrumentality status is determined at the time of the filing of the complaint.","sumSrc":"Oyez","by":{"1":"23","3":"6"}},{"t":"case","label":"El Paso Nat. Gas Co. v. Neztsosie","cite":"526 U.S. 473","y":1999,"id":"1998/98-6","sc":1,"sum":"Delivered by Justice David H. Souter, the Court held that requiring a district court to stay its hand while a tribal court determines its own jurisdiction, or the doctrine of tribal court exhaustion, does not apply in this case, which if brought in a state court would be subject to removal. \"By the Price-Anderson Act's unusual preemption provision Congress expressed an unmistakable preference for a federal forum, at the behest of the defending party,\" wrote Justice Souter.","sumSrc":"Oyez","by":{"1":"29-30"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"FHA v. Burr","cite":"309 U.S. 242","y":1940,"id":"scdb/1939-089","sc":1,"sum":"1. Under the National Housing Act, as amended, which provides that the Administrator shall, in carrying out the provisions of certain of its titles, \"be authorized, in his official capacity, to sue and be sued in any court of competent jurisdiction, State or Federal,\" the Federal Housing Administration is subject to be garnished, under state law, for moneys due to an employee; but only those funds which have been …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Frew ex rel. Frew v. Hawkins","cite":"540 U.S. 431","y":2004,"id":"2003/02-628","sc":1,"sum":"The Court held that enforcement of the consent decree does not violate the 11th Amendment.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Garcia v. United States","cite":"469 U.S. 70","y":1984,"id":"1984/83-6061","sc":1,"sum":"The language \"any money or other property of the United States\" in § 2114 includes the $1,800 belonging to the United States and entrusted to the Secret Service agent as \"flash money,\" and thus by using a pistol in an effort to rob the agent petitioners fell squarely within the prohibitions of the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Gooch v. United States","cite":"297 U.S. 124","y":1936,"id":"scdb/1935-079","sc":1,"sum":"1. An officer who is unlawfully seized and carried away to prevent the arrest of his captor is \"held for.. reward or otherwise\" within the meaning of the Federal Kidnaping Act as amended; and transportation in interstate commerce of the officer while thus restrained constitutes a violation of the Act. Act of June 22, 1932, as amended by Act of May 18, 1934.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"op":1,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Grogan v. Garner","cite":"498 U.S. 279","y":1991,"id":"1990/89-1149","sc":1,"sum":"Courts should apply the \"preponderance of the evidence\" standard. Justice John Paul Stevens, for a unanimous Supreme Court, wrote that the lack of a specified standard of evidence in section 523(a) implied that Congress had intended the preponderance of the evidence standard to be used.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Hagen v. Utah","cite":"510 U.S. 399","y":1994,"id":"1993/92-6281","sc":1,"sum":"Petitioner, an Indian, was charged in Utah state court with distribution of a controlled substance in the town of Myton, which lies within the original boundaries of the Uintah Indian Reservation on land that was opened to non-Indian settlement in 1905. The trial court rejected petitioner's claim that it lacked. jurisdiction over him because he was an Indian and the crime had been committed in \"Indian country,\" see …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Hutto v. Finney","cite":"437 U.S. 678","y":1978,"id":"1977/76-1660","sc":1,"sum":"The Court held that punitive isolation for longer than thirty days in Arkansas prisons constituted cruel and unusual punishment and violated the Constitution. Justice Stevens conceded that isolation in and of itself was not necessarily unconstitutional and may in fact serve an important, legitimate interest in administering a prison.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Intel Corp. Inv. Pol’y Comm. v. Sulyma","cite":"140 S. Ct. 768","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"1":"35","2":"19"}},{"t":"case","label":"Kerr-McGee Corp. v. Navajo Tribe","cite":"471 U.S. 195","y":1985,"id":"1984/84-68","sc":1,"sum":"The Secretary's approval of the taxes in question is not required.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Kimel v. Florida Bd. of Regents","cite":"528 U.S. 62","y":2000,"id":"1999/98-791","sc":1,"op":1,"sum":"The Court held that the ADEA contains a clear statement of Congress' intent to abrogate the states' immunity, but that the abrogation exceeds Congress' authority under the Fourteenth Amendment. \"States may discriminate on the basis of age without offending the Fourteenth Amendment if the age classification in question is rationally related to a legitimate state interest,\" wrote Justice O'Connor for the Court.","sumSrc":"Oyez","by":{"1":"33","2":"11"}},{"t":"case","label":"King v. St. Vincent’s Hosp.","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"sum":"Section 2024(d) does not limit the length of military service after which a member of the Armed Forces retains a right to civilian reemployment. Subsection (d)'s text-which specifies that any covered employee \"shall... be granted a leave... for the period required to perform active duty [and] [u]pon... release from... such duty... shall be permitted to return to [his or her] position\"-is utterly silent about any …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"sum":"The Court found that there is not geographical restriction on the \"first sale\" copyright doctrine.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Krystal Energy Co. v. Navajo Nation","cite":"357 F.3d 1055","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/357/1055/","op":1,"sum":"Holding that the Bankruptcy Code abrogates tribal sovereign immunity.","sumSrc":"opinion","by":{"1":"7","2":"5, 14, 17"}},{"t":"case","label":"Local Loan Co. v. Hunt","cite":"292 U.S. 234","y":1934,"id":"scdb/1933-054","sc":1,"sum":"1. A court of bankruptcy has jurisdiction by ancillary proceedings to enforce an order of discharge by enjoining the prosecution of suits brought against the debtor.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Loeffler v. Frank","cite":"486 U.S. 549","y":1988,"id":"1987/86-1431","sc":1,"sum":"Prejudgment interest may be awarded in a suit against the Postal Service brought under Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Maslenjak v. United States","cite":"137 S. Ct. 1918","y":2017,"id":"2016/16-309","sc":1,"sum":"The Court determined that, for a naturalized American citizen to be stripped of her citizenship, the government has to prove that she obtained her citizenship illegally; if the underlying illegality is a false statement to government officials, the government must prove that the false statement influenced the citizenship process.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"McGirt v. Oklahoma","cite":"140 S. Ct. 2452","y":2020,"id":"2019/18-9526","sc":1,"sum":"The Court held that parts of eastern Oklahoma are an Indian reservation subject to exclusive federal jurisdiction for certain crimes under the Indian Major Crimes Act.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Merrion v. Jicarilla Apache Tribe","cite":"455 U.S. 130","y":1982,"id":"1980/80-11","sc":1,"sum":"Respondent Indian Tribe, pursuant to its Revised Constitution (which had been approved by the Secretary of the Interior (Secretary) as required by the Indian Reorganization Act of 1934), enacted an ordinance (also approved by the Secretary) imposing a severance tax on oil and gas production on the tribal reservation land. Oil and gas received by the Tribe as in-kind royalty payments from lessees of mineral leases on …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 21, 27"}},{"t":"case","label":"Midlantic Nat’l Bank v. New Jersey Dep’t of Envt’l Prot.","cite":"474 U.S. 494","y":1986,"id":"1985/84-801","sc":1,"sum":"A trustee in bankruptcy may not abandon property in contravention of a state statute or regulation that is reasonably designed to protect the public health or safety from identified hazards. Congress did not intend for §554(a) to pre-empt all state and local laws. A bankruptcy court does not have the power to authorize an abandonment without formulatResources Corp., Debtor v. City of New York et al., and O'Neill, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3"}},{"t":"case","label":"Milner v. Department of Navy","cite":"562 U.S. 562","y":2011,"id":"2010/09-1163","sc":1,"sum":"The Court held that documents related to the effect of explosions from Navy exercises did not qualify for withholding under Exception 2 of the Freedom of Information Act.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Monasky v. Taglieri","cite":"140 S. Ct. 719","y":2020,"id":"2019/18-935","sc":1,"sum":"The Court held that a child’s “habitual residence” under the Hague Convention depends on the totality of the circumstances specific to the case, not categorical requirements such as an actual agreement between parents.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Montana v. United States","cite":"450 U.S. 544","y":1981,"id":"1980/79-1128","sc":1,"sum":"By a tribal regulation, the Crow Tribe of Montana sought to prohibit hunting and fishing within its reservation by anyone who is not a member of the Tribe. Relying on its purported ownership of the bed of the Big Horn River, on treaties which created its reservation, and on its inherent power as a sovereign, the Tribe claimed authority to prohibit hunting and fishing by nonmembers of the Tribe even on lands within …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7, 17"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Oklahoma Tax Comm’n v. Sac & Fox Nation","cite":"508 U.S. 114","y":1993,"id":"1992/92-259","sc":1,"sum":"Respondent Sac and Fox Nation (Tribe) is a federally recognized Indian tribe located in Oklahoma. It brought this action seeking a permanent injunction barring petitioner Oklahoma Tax Commission (Commission) from, among other things, taxing the income of tribal members who work or reside within tribal jurisdiction, and imposing the State's motor vehicle excise tax and registration fees on tribal members who live and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Pennsylvania Dep’t of Corr. v. Yeskey","cite":"524 U.S. 206","y":1998,"id":"1997/97-634","sc":1,"sum":"The Court held that under the ADA no \"public entity\" may discriminate against qualified disabled individuals due to their disability. Moreover, the Court stated that the ADA's protections extended to cover prison inmates as well as any other liberated citizen.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Plains Com. Bank v. Long Fam. Land & Cattle Co.","cite":"554 U.S. 316","y":2008,"id":"2007/07-411","sc":1,"op":1,"sum":"On this issue, the Court held unanimously that tribal courts do not have jurisdiction to hear disputes concerning non- Indian banks' sales of their own lands. Writing for the Court, Chief Justice John G. Roberts stated that although tribal courts have jurisdiction to regulate conduct occurring on tribal lands, that jurisdiction is lost once title to the land passes into the hands of non-Indians.","sumSrc":"Oyez","by":{"1":"17, 28, 29","2":"14"}},{"t":"case","label":"Puerto Rico v. Sanchez Valle","cite":"579 U.S. 59","y":2016,"id":"2015/15-108","sc":1,"sum":"The Court held that Puerto Rico and the U.S. federal government are the same sovereign entity for the purpose of the Double Jeopardy Clause.","sumSrc":"Oyez","by":{"1":"21","2":"15, 21, 22","3":"11"}},{"t":"case","label":"Reiter v. Sonotone Corp.","cite":"442 U.S. 330","y":1979,"id":"1978/78-690","sc":1,"sum":"Consumers who pay a higher price for goods purchased for personal use as a result of antitrust violations sustain an injury in their \"property\" within the meaning of § 4.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Republic of Philippines v. Pimentel","cite":"553 U.S. 851","y":2008,"id":"2007/06-1204","sc":1,"sum":"Such a required party must be joined to the suit if it is \"feasible,\" and the Court ruled that the government's inclusion was feasible in this case. The Court sent the case back to the district court with instructions to dismiss the interpleader action. Justice Anthony Kennedy delivered the opinion of the Court in which Justices John Paul Stevens and David Souter concurred in part and dissented in part.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Richlin Sec. Serv. Co. v. Chertoff","cite":"553 U.S. 571","y":2008,"id":"2007/06-1717","sc":1,"sum":"The Court held that such paralegal fees are recoverable at market rates. Justice Samuel A. Alito stated that because Richlin incurred fees for paralegal services in connection with its case, a straightforward reading of the statute demonstrates that Richlin was entitled to recover fees for the paralegal services it purchased at the market rate.","sumSrc":"Oyez","by":{"1":"14, 32"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Schindler Elevator Corp. v. United States ex rel. Kirk","cite":"563 U.S. 401","y":2011,"id":"2010/10-188","sc":1,"sum":"The Court held that a whistleblower may not use information obtained through Freedom of Information Act requests to allege violations of the Federal Claims Act by a government contractor.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Sedima, S.P.R.L. v. Imrex Co.","cite":"473 U.S. 479","y":1985,"id":"1984/84-648","sc":1,"sum":"The Racketeer Influenced and Corrupt Organizations Act (RICO), 18 U. S. C. §§ 1961-1968, which is directed at \"racketeering activity\"defined in § 1961(1) to encompass, inter alia,acts \"indictable\" under specific federal criminal provisions, including mail and wire fraud-provides in § 1964(c) for a private civil action to recover treble damages by any person injured in his business or property \"by reason of a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Sokaogon Gaming Enter. Corp. v. TushieMontgomery Assocs., Inc.","cite":"86 F.3d 656","y":1996,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/86/656/","by":{"1":"33"}},{"t":"case","label":"Southwest Airlines Co. v. Saxon","cite":"142 S. Ct. 1783","y":2022,"id":"2021/21-309","sc":1,"sum":"Airplane cargo loaders and ramp supervisors who, like petitioner Saxon, frequently load and unload airplane cargo belong to a “class of workers engaged in foreign or interstate commerce” exempt from the Federal Arbitration Act’s coverage.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"42, 43","3":"16"}},{"t":"case","label":"Strate v. A-1 Contractors","cite":"520 U.S. 438","y":1997,"id":"1996/95-1872","sc":1,"sum":"Authored by Justice Ruth Bader Ginsburg, the Court ruled that when an accident occurs on a public highway maintained by the State pursuant to a federally granted right of way over Indian reservation land, a civil action against allegedly negligent nonmembers falls within state or federal regulatory and adjudicatory governance; absent a statute or treaty authorizing the tribe to govern the conduct of nonmembers driving on the State's highway, tribal courts may not exercise jurisdiction in such cases.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"26","2":"26"}},{"t":"case","label":"Tanzin v. Tanvir","cite":"141 S. Ct. 486","y":2020,"id":"2020/19-71","sc":1,"sum":"The Religious Freedom Restoration Act of 1993’s express remedies provision, see 42 U. S. C. §2000bb–1(c), permits litigants, when appropriate, to obtain money damages against federal officials in their individual capacities.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16"}},{"t":"case","label":"Turner v. United States","cite":"248 U.S. 354","y":1919,"id":"scdb/1918-227","sc":1,"sum":"While recognized by the United States as a distinct political community, the Creek Nation leased a pasture, the lessees undertaking to fence and pay rent. When nearly completed, the fence was destroyed by the action of a Creek mob, participated in by the Creek Treasurer; and thereafter one of the lessees, assignee of the rest, sued the Creek Nation for the cost of the fence and of the assignments and for the loss of …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"United States v. Lara","cite":"541 U.S. 193","y":2004,"id":"2003/03-107","sc":1,"sum":"In an opinion written by Justice Stephen G. Breyer and joined by Chief Justice Rehnquist and three other Justices, the Court found that the right to prosecute nonmember Indians is inherent in the sovereignty of Native American tribes.","sumSrc":"Oyez","by":{"1":"14, 17, 21, 28"}},{"t":"case","label":"United States v. United States Fid. & Guar. Co.","cite":"309 U.S. 506","y":1940,"id":"scdb/1939-047","sc":1,"op":1,"sum":"In a reorganization proceeding in the District Court for the Western District of Missouri under § 77B of the Bankruptcy Act, the United States filed a claim in behalf of the Choctaw and Chickasaw Nations. The court allowed it but allowed the debtor's cross-claim for a larger amount and decreed the balance in favor of the debtor against the Nations to be \"collected in the manner provided by law.\" The validity of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14, 36"}},{"t":"case","label":"United States v. United Verde Copper Co.","cite":"196 U.S. 207","y":1905,"id":"scdb/1904-162","sc":1,"sum":"An apt and sensibl meaning must be given to words as they are used in a statute and the association of words must be regarded as designed and not as accidental, ncSiwill a word be considered an intruder if the statute can be construed reasonably without liminating that word.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"20, 23"}},{"t":"case","label":"United States v. Woods","cite":"571 U.S. 31","y":2013,"id":"2013/12-562","sc":1,"op":1,"sum":"The Court held that, under the Tax Equity and Fiscal Responsibility Act of 1982, a court in partnership-level proceedings has the right to consider the applicability of any penalty that relates to the partnership.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"United Student Aid Funds, Inc. v. Espinosa","cite":"559 U.S. 260","y":2010,"id":"2009/08-1134","sc":1,"sum":"The Court held that Chapter 13 bankruptcy plans which discharge student loans are not void if the debtor fails to provide evidence of \"undue hardship\" in an adversary proceeding.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Vermont Agency of Nat. Res. v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"1":"35-36","2":"33"}},{"t":"case","label":"West Virginia Univ. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Yellen v. Confederated Tribes of Chehalis Reser- vation","cite":"141 S. Ct. 2434","y":2021,"id":"2020/20-543","sc":1,"sum":"Alaska Native Corporations are “Indian tribe[s]” under the Indian Self-Determination and Education Assistance Act and thus eligible for funding available to “Tribal governments” under Title V of the Coronavirus Aid, Relief, and Economic Security Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"19"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"21, 40"}},{"t":"usc","label":"11 U.S.C. § 102","url":"https://www.law.cornell.edu/uscode/text/11/102","subs":["(5)"],"stext":{"head":"§102. Rules of construction","paras":[[0,"In this title—"],[1,"(1) \"after notice and a hearing\", or a similar phrase—"],[2,"(A) means after such notice as is appropriate in the particular circumstances, and such opportunity for a hearing as is appropriate in the particular circumstances; but"],[2,"(B) authorizes an act without an actual hearing if such notice is given properly and if—"],[3,"(i) such a hearing is not requested timely by a party in interest; or"],[3,"(ii) there is insufficient time for a hearing to be commenced before such act must be done, and the court authorizes such act;"],[1,"(2) \"claim against the debtor\" includes claim against property of the debtor;"],[1,"(3) \"includes\" and \"including\" are not limiting;"],[1,"(4) \"may not\" is prohibitive, and not permissive;"],[1,"(5) \"or\" is not exclusive;"],[1,"(6) \"order for relief\" means entry of an order for relief;"],[1,"(7) the singular includes the plural;"],[1,"(8) a definition, contained in a section of this title that refers to another section of this title, does not, for the purpose of such reference, affect the meaning of a term used in such other section; and"],[1,"(9) \"United States trustee\" includes a designee of the United States trustee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/102?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§102. Rules of construction","tname":"Bankruptcy","by":{"1":"23"}},{"t":"usc","label":"11 U.S.C. § 105","url":"https://www.law.cornell.edu/uscode/text/11/105","subs":["(a)"],"stext":{"head":"§105. Power of court","paras":[[0,"(a) The court may issue any order, process, or judgment that is necessary or appropriate to carry out the provisions of this title. No provision of this title providing for the raising of an issue by a party in interest shall be construed to preclude the court from, sua sponte, taking any action or making any determination necessary or appropriate to enforce or implement court orders or rules, or to prevent an abuse of process."],[0,"(b) Notwithstanding subsection (a) of this section, a court may not appoint a receiver in a case under this title."],[0,"(c) The ability of any district judge or other officer or employee of a district court to exercise any of the authority or responsibilities conferred upon the court under this title shall be determined by reference to the provisions relating to such judge, officer, or employee set forth in title 28. This subsection shall not be interpreted to exclude bankruptcy judges and other officers or employees appointed pursuant to chapter 6 of title 28 from its operation."],[0,"(d) The court, on its own motion or on the request of a party in interest—"],[1,"(1) shall hold such status conferences as are necessary to further the expeditious and economical resolution of the case; and"],[1,"(2) unless inconsistent with another provision of this title or with applicable Federal Rules of Bankruptcy Procedure, may issue an order at any such conference prescribing such limitations and conditions as the court deems appropriate to ensure that the case is handled expeditiously and economically, including an order that—"],[2,"(A) sets the date by which the trustee must assume or reject an executory contract or unexpired lease; or"],[2,"(B) in a case under chapter 11 of this title—"],[3,"(i) sets a date by which the debtor, or trustee if one has been appointed, shall file a disclosure statement and plan;"],[3,"(ii) sets a date by which the debtor, or trustee if one has been appointed, shall solicit acceptances of a plan;"],[3,"(iii) sets the date by which a party in interest other than a debtor may file a plan;"],[3,"(iv) sets a date by which a proponent of a plan, other than the debtor, shall solicit acceptances of such plan;"],[3,"(v) fixes the scope and format of the notice to be provided regarding the hearing on approval of the disclosure statement; or"],[3,"(vi) provides that the hearing on approval of the disclosure statement may be combined with the hearing on confirmation of the plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/105?type=usc&year=mostrecent&link-type=html"},"head":"§105. Power of court","tname":"Bankruptcy","by":{"1":"26","2":"26"}},{"t":"usc","label":"11 U.S.C. § 106","url":"https://www.law.cornell.edu/uscode/text/11/106","subs":["(a)","(a)(1)","(a)(2)","(a)(3)","(b)","(c)"],"stext":{"head":"§106. Waiver of sovereign immunity","paras":[[0,"(a) Notwithstanding an assertion of sovereign immunity, sovereign immunity is abrogated as to a governmental unit to the extent set forth in this section with respect to the following:"],[1,"(1) Sections 105, 106, 107, 108, 303, 346, 362, 363, 364, 365, 366, 502, 503, 505, 506, 510, 522, 523, 524, 525, 542, 543, 544, 545, 546, 547, 548, 549, 550, 551, 552, 553, 722, 724, 726, 744, 749, 764, 901, 922, 926, 928, 929, 944, 1107, 1141, 1142, 1143, 1146, 1201, 1203, 1205, 1206, 1227, 1231, 1301, 1303, 1305, and 1327 of this title."],[1,"(2) The court may hear and determine any issue arising with respect to the application of such sections to governmental units."],[1,"(3) The court may issue against a governmental unit an order, process, or judgment under such sections or the Federal Rules of Bankruptcy Procedure, including an order or judgment awarding a money recovery, but not including an award of punitive damages. Such order or judgment for costs or fees under this title or the Federal Rules of Bankruptcy Procedure against any governmental unit shall be consistent with the provisions and limitations of section 2412(d)(2)(A) of title 28."],[1,"(4) The enforcement of any such order, process, or judgment against any governmental unit shall be consistent with appropriate nonbankruptcy law applicable to such governmental unit and, in the case of a money judgment against the United States, shall be paid as if it is a judgment rendered by a district court of the United States."],[1,"(5) Nothing in this section shall create any substantive claim for relief or cause of action not otherwise existing under this title, the Federal Rules of Bankruptcy Procedure, or nonbankruptcy law."],[0,"(b) A governmental unit that has filed a proof of claim in the case is deemed to have waived sovereign immunity with respect to a claim against such governmental unit that is property of the estate and that arose out of the same transaction or occurrence out of which the claim of such governmental unit arose."],[0,"(c) Notwithstanding any assertion of sovereign immunity by a governmental unit, there shall be offset against a claim or interest of a governmental unit any claim against such governmental unit that is property of the estate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/106?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§106. Waiver of sovereign immunity","tname":"Bankruptcy","by":{"1":"24, 1-3, 6-7, 9-10, 15, 19, 24, 32, 34, 36, 15, 24, 3-4, 15, 3-4, 15","2":"27, 34, 1-3, 7, 10, 13, 16, 21, 23, 25, 2, 3, 28, 28"}},{"t":"usc","label":"11 U.S.C. § 107","url":"https://www.law.cornell.edu/uscode/text/11/107","subs":["(c)(2)"],"stext":{"head":"§107. Public access to papers","paras":[[0,"(a) Except as provided in subsections (b) and (c) and subject to section 112, a paper filed in a case under this title and the dockets of a bankruptcy court are public records and open to examination by an entity at reasonable times without charge."],[0,"(b) On request of a party in interest, the bankruptcy court shall, and on the bankruptcy court's own motion, the bankruptcy court may—"],[1,"(1) protect an entity with respect to a trade secret or confidential research, development, or commercial information; or"],[1,"(2) protect a person with respect to scandalous or defamatory matter contained in a paper filed in a case under this title."],[0,"(c)(1) The bankruptcy court, for cause, may protect an individual, with respect to the following types of information to the extent the court finds that disclosure of such information would create undue risk of identity theft or other unlawful injury to the individual or the individual's property:"],[1,"(A) Any means of identification (as defined in section 1028(d) of title 18) contained in a paper filed, or to be filed, in a case under this title."],[1,"(B) Other information contained in a paper described in subparagraph (A)."],[0,"(2) Upon ex parte application demonstrating cause, the court shall provide access to information protected pursuant to paragraph (1) to an entity acting pursuant to the police or regulatory power of a domestic governmental unit."],[0,"(3) The United States trustee, bankruptcy administrator, trustee, and any auditor serving under section 586(f) of title 28—"],[1,"(A) shall have full access to all information contained in any paper filed or submitted in a case under this title; and"],[1,"(B) shall not disclose information specifically protected by the court under this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/107?type=usc&year=mostrecent&link-type=html"},"head":"§107. Public access to papers","tname":"Bankruptcy","by":{"1":"28","2":"30"}},{"t":"usc","label":"11 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/11/301","stext":{"head":"§301. Voluntary cases","paras":[[0,"(a) A voluntary case under a chapter of this title is commenced by the filing with the bankruptcy court of a petition under such chapter by an entity that may be a debtor under such chapter."],[0,"(b) The commencement of a voluntary case under a chapter of this title constitutes an order for relief under such chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/301?type=usc&year=mostrecent&link-type=html"},"head":"§301. Voluntary cases","tname":"Bankruptcy","by":{"1":"3, 15, 24","2":"2"}},{"t":"usc","label":"11 U.S.C. § 362","url":"https://www.law.cornell.edu/uscode/text/11/362","subs":["(a)","(a)(6)","(b)(4)","(b)(9)","(b)(18)","(b)(26)","(k)","(k)(1)"],"stext":{"head":"§362. Automatic stay","paras":[[0,"(a) Except as provided in subsection (b) of this section, a petition filed under section 301, 302, or 303 of this title, or an application filed under section 5(a)(3) of the Securities Investor Protection Act of 1970, operates as a stay, applicable to all entities, of—"],[1,"(1) the commencement or continuation, including the issuance or employment of process, of a judicial, administrative, or other action or proceeding against the debtor that was or could have been commenced before the commencement of the case under this title, or to recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(2) the enforcement, against the debtor or against property of the estate, of a judgment obtained before the commencement of the case under this title;"],[1,"(3) any act to obtain possession of property of the estate or of property from the estate or to exercise control over property of the estate;"],[1,"(4) any act to create, perfect, or enforce any lien against property of the estate;"],[1,"(5) any act to create, perfect, or enforce against property of the debtor any lien to the extent that such lien secures a claim that arose before the commencement of the case under this title;"],[1,"(6) any act to collect, assess, or recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(7) the setoff of any debt owing to the debtor that arose before the commencement of the case under this title against any claim against the debtor; and"],[1,"(8) the commencement or continuation of a proceeding before the United States Tax Court concerning a tax liability of a debtor that is a corporation for a taxable period the bankruptcy court may determine or concerning the tax liability of a debtor who is an individual for a taxable period ending before the date of the order for relief under this title."],[0,"(b) The filing of a petition under section 301, 302, or 303 of this title, or of an application under section 5(a)(3) of the Securities Investor Protection Act of 1970, does not operate as a stay—"],[1,"(1) under subsection (a) of this section, of the commencement or continuation of a criminal action or proceeding against the debtor;"],[1,"(2) under subsection (a)—"],[2,"(A) of the commencement or continuation of a civil action or proceeding—"],[3,"(i) for the establishment of paternity;"],[3,"(ii) for the establishment or modification of an order for domestic support obligations;"],[3,"(iii) concerning child custody or visitation;"],[3,"(iv) for the dissolution of a marriage, except to the extent that such proceeding seeks to determine the division of property that is property of the estate; or"],[3,"(v) regarding domestic violence;"],[2,"(B) of the collection of a domestic support obligation from property that is not property of the estate;"],[2,"(C) with respect to the withholding of income that is property of the estate or property of the debtor for payment of a domestic support obligation under a judicial or administrative order or a statute;"],[2,"(D) of the withholding, suspension, or restriction of a driver's license, a professional or occupational license, or a recreational license, under State law, as specified in section 466(a)(16) of the Social Security Act;"],[2,"(E) of the reporting of overdue support owed by a parent to any consumer reporting agency as specified in section 466(a)(7) of the Social Security Act;"],[2,"(F) of the interception of a tax refund, as specified in sections 464 and 466(a)(3) of the Social Security Act or under an analogous State law; or"],[2,"(G) of the enforcement of a medical obligation, as specified under title IV of the Social Security Act;"],[1,"(3) under subsection (a) of this section, of any act to perfect, or to maintain or continue the perfection of, an interest in property to the extent that the trustee's rights and powers are subject to such perfection under section 546(b) of this title or to the extent that such act is accomplished within the period provided under section 547(e)(2)(A) of this title;"],[1,"(4) under paragraph (1), (2), (3), or (6) of subsection (a) of this section, of the commencement or continuation of an action or proceeding by a governmental unit or any organization exercising authority under the Convention on the Prohibition of the Development, Production, Stockpiling and Use of Chemical Weapons and on Their Destruction, opened for signature on January 13, 1993, to enforce such governmental unit's or organization's police and regulatory power, including the enforcement of a judgment other than a money judgment, obtained in an action or proceeding by the governmental unit to enforce such governmental unit's or organization's police or regulatory power;"],[1,"[(5) Repealed. Pub. L. 105–277, div. I, title VI, §603(1), Oct. 21, 1998, 112 Stat. 2681–866;]"],[1,"(6) under subsection (a) of this section, of the exercise by a commodity broker, forward contract merchant, stockbroker, financial institution, financial participant, or securities clearing agency of any contractual right (as defined in section 555 or 556) under any security agreement or arrangement or other credit enhancement forming a part of or related to any commodity contract, forward contract or securities contract, or of any contractual right (as defined in section 555 or 556) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such contracts, including any master agreement for such contracts;"],[1,"(7) under subsection (a) of this section, of the exercise by a repo participant or financial participant of any contractual right (as defined in section 559) under any security agreement or arrangement or other credit enhancement forming a part of or related to any repurchase agreement, or of any contractual right (as defined in section 559) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such agreements, including any master agreement for such agreements;"],[1,"(8) under subsection (a) of this section, of the commencement of any action by the Secretary of Housing and Urban Development to foreclose a mortgage or deed of trust in any case in which the mortgage or deed of trust held by the Secretary is insured or was formerly insured under the National Housing Act and covers property, or combinations of property, consisting of five or more living units;"],[1,"(9) under subsection (a), of—"],[2,"(A) an audit by a governmental unit to determine tax liability;"],[2,"(B) the issuance to the debtor by a governmental unit of a notice of tax deficiency;"],[2,"(C) a demand for tax returns; or"],[2,"(D) the making of an assessment for any tax and issuance of a notice and demand for payment of such an assessment (but any tax lien that would otherwise attach to property of the estate by reason of such an assessment shall not take effect unless such tax is a debt of the debtor that will not be discharged in the case and such property or its proceeds are transferred out of the estate to, or otherwise revested in, the debtor)."],[1,"(10) under subsection (a) of this section, of any act by a lessor to the debtor under a lease of nonresidential real property that has terminated by the expiration of the stated term of the lease before the commencement of or during a case under this title to obtain possession of such property;"],[1,"(11) under subsection (a) of this section, of the presentment of a negotiable instrument and the giving of notice of and protesting dishonor of such an instrument;"],[1,"(12) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Transportation under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage, or a security interest in or relating to a vessel or vessel under construction, held by the Secretary of Transportation under chapter 537 of title 46 or section 109(h) of title 49, or under applicable State law;"],[1,"(13) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Commerce under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage in a vessel or a mortgage, deed of trust, or other security interest in a fishing facility held by the Secretary of Commerce under chapter 537 of title 46;"],[1,"(14) under subsection (a) of this section, of any action by an accrediting agency regarding the accreditation status of the debtor as an educational institution;"],[1,"(15) under subsection (a) of this section, of any action by a State licensing body regarding the licensure of the debtor as an educational institution;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/362?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§362. Automatic stay","tname":"Bankruptcy","by":{"1":"3, 15, 24, 3, 5, 25, 3, 15, 28, 27, 27, 27, 6, 3, 15","2":"3, 3, 24, 26, 30, 30, 30, 30, 3, 4, 26"}},{"t":"usc","label":"11 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/11/501","by":{"1":"27","2":"30"}},{"t":"usc","label":"11 U.S.C. § 503","url":"https://www.law.cornell.edu/uscode/text/11/503","subs":["(b)(1)(B)","(b)(1)(D)"],"by":{"1":"27, 27"}},{"t":"usc","label":"11 U.S.C. § 507","url":"https://www.law.cornell.edu/uscode/text/11/507","subs":["(a)(1)(A)","(a)(8)","(a)(1)(B)"],"by":{"1":"28, 27","2":"31, 31, 30"}},{"t":"usc","label":"11 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/11/523","subs":["(a)(1)(A)","(a)(5)","(a)(7)"],"by":{"1":"27, 28, 28","2":"31, 30"}},{"t":"usc","label":"11 U.S.C. § 524","url":"https://www.law.cornell.edu/uscode/text/11/524","subs":["(a)(2)"],"by":{"1":"24, 25, 26","2":"26"}},{"t":"usc","label":"11 U.S.C. § 901","url":"https://www.law.cornell.edu/uscode/text/11/901","by":{"1":"11, 24"}},{"t":"usc","label":"11 U.S.C. § 944","url":"https://www.law.cornell.edu/uscode/text/11/944","subs":["(a)"],"by":{"1":"24, 25"}},{"t":"usc","label":"11 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/11/1101","by":{"1":"11, 24, 30","2":"30"}},{"t":"usc","label":"11 U.S.C. § 1141","url":"https://www.law.cornell.edu/uscode/text/11/1141","subs":["(a)","(c)"],"by":{"1":"24, 25, 25"}},{"t":"usc","label":"11 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/11/1201","by":{"1":"11, 24"}},{"t":"usc","label":"11 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/11/1227","subs":["(a)","(c)"],"by":{"1":"24, 25, 25"}},{"t":"usc","label":"11 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/11/1301","by":{"1":"1, 4, 5, 11, 24","2":"30"}},{"t":"usc","label":"11 U.S.C. § 1327","url":"https://www.law.cornell.edu/uscode/text/11/1327","subs":["(a)","(c)","(b)"],"by":{"1":"24, 25, 25","2":"25, 25"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"1":"35"}},{"t":"usc","label":"33 U.S.C. § 1365","url":"https://www.law.cornell.edu/uscode/text/33/1365","subs":["(a)(1)"],"by":{"1":"35"}},{"t":"usc","label":"28 U.S.C. § 3001","url":"https://www.law.cornell.edu/uscode/text/28/3001","by":{"1":"35"}},{"t":"usc","label":"28 U.S.C. § 3002","url":"https://www.law.cornell.edu/uscode/text/28/3002","subs":["(7)","(10)"],"by":{"1":"35, 35"}},{"t":"usc","label":"28 U.S.C. § 3104","url":"https://www.law.cornell.edu/uscode/text/28/3104","by":{"1":"35"}},{"t":"usc","label":"28 U.S.C. § 3205","url":"https://www.law.cornell.edu/uscode/text/28/3205","subs":["(a)"],"by":{"1":"35"}},{"t":"usc","label":"25 U.S.C. § 2701","url":"https://www.law.cornell.edu/uscode/text/25/2701","by":{"1":"35"}},{"t":"law","label":"Indian Self-Determination and Education Assistance Act, Pub. L. No. 93-638","url":"https://www.govinfo.gov/link/statute/88/2203","by":{"1":"18"}},{"t":"usc","label":"25 U.S.C. § 5321","url":"https://www.law.cornell.edu/uscode/text/25/5321","subs":["(c)(3)(A)"],"by":{"1":"35","2":"19"}},{"t":"law","label":"Pub. L. No. 103-413","url":"https://www.govinfo.gov/link/statute/108/4250","by":{"1":"19"}},{"t":"usc","label":"42 U.S.C. § 6901","url":"https://www.law.cornell.edu/uscode/text/42/6901","by":{"1":"35"}},{"t":"usc","label":"42 U.S.C. § 6903","url":"https://www.law.cornell.edu/uscode/text/42/6903","subs":["(13)","(15)"],"by":{"1":"35, 35","2":"19, 19"}},{"t":"usc","label":"42 U.S.C. § 6972","url":"https://www.law.cornell.edu/uscode/text/42/6972","subs":["(a)(1)(A)"],"stext":{"head":"§6972. Citizen suits","paras":[[0,"(a) In general"],[0,"Except as provided in subsection (b) or (c) of this section, any person may commence a civil action on his own behalf—"],[1,"(1)(A) against any person (including (a) the United States, and (b) any other governmental instrumentality or agency, to the extent permitted by the eleventh amendment to the Constitution) who is alleged to be in violation of any permit, standard, regulation, condition, requirement, prohibition, or order which has become effective pursuant to this chapter; or"],[1,"(B) against any person, including the United States and any other governmental instrumentality or agency, to the extent permitted by the eleventh amendment to the Constitution, and including any past or present generator, past or present transporter, or past or present owner or operator of a treatment, storage, or disposal facility, who has contributed or who is contributing to the past or present handling, storage, treatment, transportation, or disposal of any solid or hazardous waste which may present an imminent and substantial endangerment to health or the environment; or"],[1,"(2) against the Administrator where there is alleged a failure of the Administrator to perform any act or duty under this chapter which is not discretionary with the Administrator."],[0,"Any action under paragraph (a)(1) of this subsection shall be brought in the district court for the district in which the alleged violation occurred or the alleged endangerment may occur. Any action brought under paragraph (a)(2) of this subsection may be brought in the district court for the district in which the alleged violation occurred or in the District Court of the District of Columbia. The district court shall have jurisdiction, without regard to the amount in controversy or the citizenship of the parties, to enforce the permit, standard, regulation, condition, requirement, prohibition, or order, referred to in paragraph (1)(A), to restrain any person who has contributed or who is contributing to the past or present handling, storage, treatment, transportation, or disposal of any solid or hazardous waste referred to in paragraph (1)(B), to order such person to take such other action as may be necessary, or both, or to order the Administrator to perform the act or duty referred to in paragraph (2), as the case may be, and to apply any appropriate civil penalties under section 6928(a) and (g) of this title."],[0,"(b) Actions prohibited"],[0,"(1) No action may be commenced under subsection (a)(1)(A) of this section—"],[1,"(A) prior to 60 days after the plaintiff has given notice of the violation to—"],[2,"(i) the Administrator;"],[2,"(ii) the State in which the alleged violation occurs; and"],[2,"(iii) to any alleged violator of such permit, standard, regulation, condition, requirement, prohibition, or order,"],[1,"except that such action may be brought immediately after such notification in the case of an action under this section respecting a violation of subchapter III of this chapter; or"],[1,"(B) if the Administrator or State has commenced and is diligently prosecuting a civil or criminal action in a court of the United States or a State to require compliance with such permit, standard, regulation, condition, requirement, prohibition, or order."],[0,"In any action under subsection (a)(1)(A) in a court of the United States, any person may intervene as a matter of right."],[0,"(2)(A) No action may be commenced under subsection (a)(1)(B) of this section prior to ninety days after the plaintiff has given notice of the endangerment to—"],[1,"(i) the Administrator;"],[1,"(ii) the State in which the alleged endangerment may occur;"],[1,"(iii) any person alleged to have contributed or to be contributing to the past or present handling, storage, treatment, transportation, or disposal of any solid or hazardous waste referred to in subsection (a)(1)(B),"],[0,"except that such action may be brought immediately after such notification in the case of an action under this section respecting a violation of subchapter III of this chapter."],[0,"(B) No action may be commenced under subsection (a)(1)(B) of this section if the Administrator, in order to restrain or abate acts or conditions which may have contributed or are contributing to the activities which may present the alleged endangerment—"],[1,"(i) has commenced and is diligently prosecuting an action under section 6973 of this title or under section 106 of the Comprehensive Environmental Response, Compensation and Liability Act of 1980 [42 U.S.C. 9606],1"],[1,"(ii) is actually engaging in a removal action under section 104 of the Comprehensive Environmental Response, Compensation and Liability Act of 1980 [42 U.S.C. 9604];"],[1,"(iii) has incurred costs to initiate a Remedial Investigation and Feasibility Study under section 104 of the Comprehensive Environmental Response, Compensation and Liability Act of 1980 [42 U.S.C. 9604] and is diligently proceeding with a remedial action under that Act [42 U.S.C. 9601 et seq.]; or"],[1,"(iv) has obtained a court order (including a consent decree) or issued an administrative order under section 106 of the Comprehensive Environmental Response, Compensation and Liability Act of 980 2 [42 U.S.C. 9606] or section 6973 of this title pursuant to which a responsible party is diligently conducting a removal action, Remedial Investigation and Feasibility Study (RIFS), or proceeding with a remedial action."],[0,"In the case of an administrative order referred to in clause (iv), actions under subsection (a)(1)(B) are prohibited only as to the scope and duration of the administrative order referred to in clause (iv)."],[0,"(C) No action may be commenced under subsection (a)(1)(B) of this section if the State, in order to restrain or abate acts or conditions which may have contributed or are contributing to the activities which may present the alleged endangerment—"],[1,"(i) has commenced and is diligently prosecuting an action under subsection (a)(1)(B);"],[1,"(ii) is actually engaging in a removal action under section 104 of the Comprehensive Environmental Response, Compensation and Liability Act of 1980 [42 U.S.C. 9604]; or"],[1,"(iii) has incurred costs to initiate a Remedial Investigation and Feasibility Study under section 104 of the Comprehensive Environmental Response, Compensation and Liability Act of 1980 [42 U.S.C. 9604] and is diligently proceeding with a remedial action under that Act [42 U.S.C. 9601 et seq.]."],[0,"(D) No action may be commenced under subsection (a)(1)(B) by any person (other than a State or local government) with respect to the siting of a hazardous waste treatment, storage, or a disposal facility, nor to restrain or enjoin the issuance of a permit for such facility."],[0,"(E) In any action under subsection (a)(1)(B) in a court of the United States, any person may intervene as a matter of right when the applicant claims an interest relating to the subject of the action and he is so situated that the disposition of the action may, as a practical matter, impair or impede his ability to protect that interest, unless the Administrator or the State shows that the applicant's interest is adequately represented by existing parties."],[0,"(F) Whenever any action is brought under subsection (a)(1)(B) in a court of the United States, the plaintiff shall serve a copy of the complaint on the Attorney General of the United States and with the Administrator."],[0,"(c) Notice"],[0,"No action may be commenced under paragraph (a)(2) of this section prior to sixty days after the plaintiff has given notice to the Administrator that he will commence such action, except that such action may be brought immediately after such notification in the case of an action under this section respecting a violation of subchapter III. Notice under this subsection shall be given in such manner as the Administrator shall prescribe by regulation. Any action respecting a violation under this chapter may be brought under this section only in the judicial district in which such alleged violation occurs."],[0,"(d) Intervention"],[0,"In any action under this section the Administrator, if not a party, may intervene as a matter of right."],[0,"(e) Costs"],[0,"The court, in issuing any final order in any action brought pursuant to this section or section 6976 of this title, may award costs of litigation (including reasonable attorney and expert witness fees) to the prevailing or substantially prevailing party, whenever the court determines such an award is appropriate. The court may, if a temporary restraining order or preliminary injunction is sought, require the filing of a bond or equivalent security in accordance with the Federal Rules of Civil Procedure."],[0,"(f) Other rights preserved"],[0,"Nothing in this section shall restrict any right which any person (or class of persons) may have under any statute or common law to seek enforcement of any standard or requirement relating to the management of solid waste or hazardous waste, or to seek any other relief (including relief against the Administrator or a State agency)."],[0,"(g) Transporters"],[0,"A transporter shall not be deemed to have contributed or to be contributing to the handling, storage, treatment, or disposal, referred to in subsection (a)(1)(B) taking place after such solid waste or hazardous waste has left the possession or control of such transporter, if the transportation of such waste was under a sole contractual arrangement arising from a published tariff and acceptance for carriage by common carrier by rail and such transporter has exercised due care in the past or present handling, storage, treatment, transportation and disposal of such waste."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/6972?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6972. Citizen suits","tname":"The Public Health and Welfare","by":{"1":"35"}},{"t":"usc","label":"42 U.S.C. § 300j-9","url":"https://www.law.cornell.edu/uscode/text/42/300j-9","subs":["(i)"],"by":{"1":"35"}},{"t":"law","label":"Pub. L. No. 107-204","url":"https://www.govinfo.gov/link/plaw/107/public/204","by":{"1":"39"}},{"t":"usc","label":"18 U.S.C. § 1519","url":"https://www.law.cornell.edu/uscode/text/18/1519","by":{"1":"39"}},{"t":"usc","label":"5 U.S.C. § 3331","url":"https://www.law.cornell.edu/uscode/text/5/3331","stext":{"head":"§3331. Oath of office","paras":[[0,"An individual, except the President, elected or appointed to an office of honor or profit in the civil service or uniformed services, shall take the following oath: \"I, AB, do solemnly swear (or affirm) that I will support and defend the Constitution of the United States against all enemies, foreign and domestic; that I will bear true faith and allegiance to the same; that I take this obligation freely, without any mental reservation or purpose of evasion; and that I will well and faithfully discharge the duties of the office on which I am about to enter. So help me God.\" This section does not affect other oaths required by law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/3331?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3331. Oath of office","tname":"Government Organization and Employees","by":{"1":"22"}},{"t":"usc","label":"8 U.S.C. § 1448","url":"https://www.law.cornell.edu/uscode/text/8/1448","subs":["(a)"],"by":{"1":"22"}},{"t":"usc","label":"10 U.S.C. § 502","url":"https://www.law.cornell.edu/uscode/text/10/502","subs":["(a)"],"by":{"1":"22"}},{"t":"usc","label":"15 U.S.C. § 57b-2b","url":"https://www.law.cornell.edu/uscode/text/15/57b-2b","subs":["(d)"],"by":{"1":"22"}},{"t":"usc","label":"15 U.S.C. § 1152","url":"https://www.law.cornell.edu/uscode/text/15/1152","subs":["(a)"],"by":{"1":"22"}},{"t":"reg","label":"45 C.F.R. pt. 309","url":"https://www.ecfr.gov/current/title-45/part-309","by":{"1":"29"}},{"t":"reg","label":"ADMINISTRATIVE MATERIALS Final Rule, National Organic Program, 65 Fed. Reg. 80,548","url":"https://www.govinfo.gov/link/fr/65/80548","by":{"1":"34"}},{"t":"reg","label":"Final Rule, Procedures for Establishing That an American Indian Group Exists as an Indian Tribe, 43 Fed. Reg. 39,361","url":"https://www.govinfo.gov/link/fr/43/39361","by":{"1":"18"}},{"t":"reg","label":"Proposed Rule, National Organic Program, 65 Fed. Reg. 13,512","url":"https://www.govinfo.gov/link/fr/65/13512","by":{"1":"34"}},{"t":"case","label":"Begier v. IRS","cite":"496 U.S. 53","y":1990,"id":"1989/89-393","sc":1,"sum":"AIA's trust-fund tax payments from its general accounts were transfers of property held in trust and therefore cannot be avoided as preferences.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"CSX Transp., Inc. v. Georgia State Bd. of Equalization","cite":"552 U.S. 9","y":2007,"id":"2007/06-1287","sc":1,"sum":"The Court reversed the 11th Circuit in a unanimous decision. Writing for the Court, Chief Justice John G. Roberts, Jr. stated that courts cannot blindly accept the states' market valuations without potentially endorsing the type of discriminatory tax practices that the 4-R Act was designed to thwart.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Cook v. Gralike","cite":"531 U.S. 510","y":2001,"id":"2000/99-929","sc":1,"sum":"The Court held that Article VIII of the Missouri Constitution, which required the placement of negative labels next to state candidates for federal office, who failed to comply with voter-mandated support of federal term limits, was an unconstitutional attempt to regulate electoral outcomes, rather than a permissible regulation of state elections.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"De Lima v. Bidwell","cite":"182 U.S. 1","y":1901,"id":"scdb/1900-058","sc":1,"sum":"By the Customs Administrative Act of 1890 an appeal is given from the decision of the collector “as to the rate and amount of the duties chargeable upon imported merchandise,” to the Board of General Appraisers, who are authorized to decide “ as to the construction of the law and the facts respecting the classification Of such merchandise; and the rate of duties imposed thereon under such classification;” but where …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Edelman v. Jordan","cite":"415 U.S. 651","y":1974,"id":"1973/72-1410","sc":1,"sum":"The Eleventh Amendment of the Constitution bars that portion of the District Court's decree that ordered retroactive pavment of benefits.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"HollyFrontier Cheyenne Ref., LLC v. Renewable Fuels Ass’n","cite":"141 S. Ct. 2172","y":2021,"id":"2020/20-472","sc":1,"sum":"Under the renewable fuel program’s fuel blending requirements for domestic refineries, a small refinery that previously received a hardship exemption may obtain an “extension” under 42 U. S. C. §7545(o)(9)(B)(i) even if the refinery did not seek a hardship exemption every year after initially doing so.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"13"}},{"t":"case","label":"Inyo Cnty. v. Paiute-Shoshone Indians of the Bishop Cmty. of the Bishop Colony","cite":"538 U.S. 701","y":2003,"id":"2002/02-281","sc":1,"sum":"The Court held that, in the situation presented, the Tribe does not qualify as a \"person\" who may sue under section 1983 to vindicate the sovereign right it here claims.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"op":1,"sum":"The Court decided that a statement regarding a specific asset can be a “statement respecting the debtor’s . . . financial condition” under section 523(a)(2)(B) of the Bankruptcy Code.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Mohamad v. Palestinian Auth.","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"op":3,"sum":"The Court held that the word \"individual\" in the Torture Victim Protection Act means a natural person and does not impose any liability against organizations.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Norfolk & W. Ry. Co. v. American Train Dispatchers’ Ass’n","cite":"499 U.S. 117","y":1991,"id":"1990/89-1027","sc":1,"sum":"The § 11341(a) exemption \"from all other law\" includes a carrier's legal obligations under a collective-bargaining agreement when necessary to carry out an ICC-approved transaction. The exemption's language, as correctly interpreted by the ICC, is clear, broad, and unqualified, bespeaking an unambiguous congressional intent to include any obstacle imposed by law. That language neither admits of a distinction between …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Paroline v. United States","cite":"572 U.S. 434","y":2014,"id":"2013/12-8561","sc":1,"op":5,"ar":1,"sum":"The Court ruled that to recover restitution, either the government or the victim must establish a causal relationship between the defendant's conduct and the victim's harm or damages.","sumSrc":"Oyez","by":{"2":"17","3":"7, 8"}},{"t":"case","label":"Ritzen Grp., Inc. v. Jackson Masonry, LLC","cite":"140 S. Ct. 582","y":2020,"id":"2019/18-938","sc":1,"sum":"The Court held that a bankruptcy court’s order unreservedly denying relief from the automatic stay of creditor debt-collection efforts outside the bankruptcy forum is final and immediately appealable.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"case","label":"Roberts v. Sea-Land Servs., Inc.","cite":"566 U.S. 93","y":2012,"id":"2011/10-1399","sc":1,"op":3,"sum":"The Court held that the Longshore Act sets the period when an injured worker is awarded disability compensation as the fiscal year when the worker first becomes entitled to compensation.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Rousey v. Jacoway","cite":"544 U.S. 320","y":2005,"id":"2004/03-1407","sc":1,"sum":"The Court held that the Rouseys could exempt IRA assets from their bankruptcy estate. IRAs met both federal requirements dealing with exemptions from bankruptcy: They were \"similar plans or contracts\" to the exemptions enumerated and they \"conferred a right to receive payment on account of age.\".","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"sum":"The Court held that the Foreign Sovereign Immunities Act does not extend to an individual acting in his official capacity on behalf of the foreign state.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Seminole Tribe v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"2":"11, 24"}},{"t":"case","label":"South Carolina v. Catawba Indian Tribe, Inc.","cite":"476 U.S. 498","y":1986,"id":"1985/84-782","sc":1,"op":1,"sum":"The explicit redefinition of the relationship between the Federal Government and respondent Tribe reflected in the Catawba Act's clear language requires the application of the state statute of limitations to the Tribe's claim. But whether that statute bars the claim should be determined by the Court of Appeals on remand. Pp. 506-511. 740 F. 2d 305, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"Stellwagen v. Clum","cite":"245 U.S. 605","y":1918,"id":"scdb/1917-183","sc":1,"sum":"The Bankruptcy. Act as it was on the dates herein mentioned (February 2,1910, November 9,1910) did not operate to suspend § 6343 of the Revised Statutes of Ohio as it stood February 2, 1910, or the sections into which that section was divided and numbered by the General Code of Ohio, approved February 15, 1910, viz: §§ 11102-11105, as such sections existed May 5,1910.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Tarrant Reg’l Water Dist. v. Herrmann","cite":"569 U.S. 614","y":2013,"id":"2012/11-889","sc":1,"sum":"The Court held that Congress’ approval of an interstate water compact does not violate the Commerce Clause and that the compact does respect state lines.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Taylor v. United States","cite":"579 U.S. 301","y":2016,"id":"2015/14-6166","sc":1,"op":1,"sum":"The Court determined that, in a prosecution for robbery under the Hobbs Act, the commerce element is satisfied when the government shows that the defendant robbed a drug dealer of drugs or drug proceeds.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"United States v. Testan","cite":"424 U.S. 392","y":1976,"id":"1975/74-753","sc":1,"sum":"Respondent Government trial attorneys with civil service grade GS-13 classifications requested their employing agency to reclassify their positions to grade GS-14, contending that their duties and responsibilities met the requirements for the higher grade and were identical to those of other trial attorneys classified as GS-14 in another agency, and that under the principle of \"equal pay for substantially equal …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"11"}},{"t":"const","label":"Article I, Section 8, Clause 3","clauses":[["commerce","Commerce Clause"]],"text":"To regulate Commerce with foreign Nations, and among the several States, and with the Indian Tribes;","by":{"2":"21"}},{"t":"usc","label":"11 U.S.C. § 109","url":"https://www.law.cornell.edu/uscode/text/11/109","by":{"2":"32"}},{"t":"usc","label":"11 U.S.C. § 307","url":"https://www.law.cornell.edu/uscode/text/11/307","by":{"2":"2"}},{"t":"usc","label":"11 U.S.C. § 502","url":"https://www.law.cornell.edu/uscode/text/11/502","subs":["(b)(9)"],"by":{"2":"30"}},{"t":"usc","label":"11 U.S.C. § 505","url":"https://www.law.cornell.edu/uscode/text/11/505","subs":["(a)(2)(B)"],"by":{"2":"30"}},{"t":"usc","label":"11 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/11/542","by":{"2":"26"}},{"t":"usc","label":"11 U.S.C. § 545","url":"https://www.law.cornell.edu/uscode/text/11/545","by":{"2":"26"}},{"t":"usc","label":"11 U.S.C. § 547","url":"https://www.law.cornell.edu/uscode/text/11/547","by":{"2":"26, 27"}},{"t":"usc","label":"11 U.S.C. § 548","url":"https://www.law.cornell.edu/uscode/text/11/548","by":{"2":"26"}},{"t":"usc","label":"11 U.S.C. § 549","url":"https://www.law.cornell.edu/uscode/text/11/549","by":{"2":"26"}},{"t":"usc","label":"11 U.S.C. § 550","url":"https://www.law.cornell.edu/uscode/text/11/550","by":{"2":"26, 27"}},{"t":"usc","label":"11 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/11/701","by":{"2":"30"}},{"t":"usc","label":"11 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/11/704","subs":["(a)(8)"],"by":{"2":"30"}},{"t":"usc","label":"11 U.S.C. § 1106","url":"https://www.law.cornell.edu/uscode/text/11/1106","subs":["(a)"],"by":{"2":"30"}},{"t":"usc","label":"11 U.S.C. § 1305","url":"https://www.law.cornell.edu/uscode/text/11/1305","subs":["(a)(1)"],"by":{"2":"30"}},{"t":"usc","label":"11 U.S.C. § 1501","url":"https://www.law.cornell.edu/uscode/text/11/1501","by":{"2":"31"}},{"t":"usc","label":"11 U.S.C. § 1519","url":"https://www.law.cornell.edu/uscode/text/11/1519","subs":["(d)"],"by":{"2":"31"}},{"t":"usc","label":"11 U.S.C. § 1521","url":"https://www.law.cornell.edu/uscode/text/11/1521","subs":["(d)"],"by":{"2":"31"}},{"t":"usc","label":"28 U.S.C. § 581-589a","url":"https://www.law.cornell.edu/uscode/text/28/581-589a","by":{"2":"2"}},{"t":"reg","label":"Exec. Order No. 13175, Consultation and Coordination with Indian Tribal Governments, 65 Fed. Reg. 67,249","url":"https://www.govinfo.gov/link/fr/65/67249","by":{"2":"15"}},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"143 S. Ct. 665","y":2023,"id":"2022/21-908","sc":1,"sum":"Pursuant to §523(a)(2)(A) of the Bankruptcy Code, a debtor like Kate Bartenwerfer who is liable for her partner’s fraud cannot discharge that debt in bankruptcy, regardless of her own culpability.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"17"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"3":"9"}},{"t":"case","label":"New Mexico v. Mescalero Apache Tribe","cite":"462 U.S. 324","y":1983,"id":"1982/82-331","sc":1,"sum":"The application of New Mexico's laws to on-reservation hunting and fishing by nonmembers of the Tribe is pre-empted by the operation of federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"11"}},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"139 S. Ct. 1881","y":2019,"id":"2018/18-389","sc":1,"sum":"Under the Outer Continental Shelf Lands Act, where federal law addresses the relevant issue, state law is not adopted as surrogate federal law on the Outer Continental Shelf.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"11"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Tr.","cite":"579 U.S. 115","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Raygor v. Regents of Univ. of Minn.","cite":"534 U.S. 533","y":2002,"id":"2001/00-1514","sc":1,"sum":"The Court held that the Board of Regents of the University of Minnesota never consented to suit in federal court on Raygor and Goodrich's state law claims and that the federal supplemental jurisdiction statute does not toll the period of limitations for state law claims asserted against nonconsenting state defendants that are dismissed on Eleventh Amendment grounds.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Ysleta del Sur Pueblo v. Texas","cite":"142 S. Ct. 1929","y":2022,"id":"2021/20-493","sc":1,"op":1,"sum":"The federal legislation at issue—the Ysleta del Sur and Alabama and Coushatta Indian Tribes of Texas Restoration Act—bans as a matter of federal law on tribal lands only those gaming activities also banned in Texas.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"11"}},{"t":"case","label":"ZF Auto. US, Inc. v. Luxshare, Ltd.","cite":"142 S. Ct. 2078","y":2022,"id":"2021/21-401","sc":1,"sum":"Although 28 U. S. C. §1782(a) permits a district court to order discovery “for use in a proceeding in a foreign or international tribunal,” only a governmental or intergovernmental adjudicative body may qualify as such a tribunal, and the arbitration panels in these cases are not such adjudicative bodies.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"9"}},{"t":"usc","label":"28 U.S.C. § 1603","url":"https://www.law.cornell.edu/uscode/text/28/1603","subs":["(b)"],"by":{"3":"6"}}]};